    ["How many enemies it shows (3 to 8). Any more: a \"+2 more\" line."] = "设置敌人列表显示数量（3–8），超出部分以“另有 N 个”汇总。",
    ["Enemy List: Casts"] = "敌人施法条",
    ["On: a slim cast bar under an enemy while it casts, with the spell's name; grey with a shield when it can't be interrupted. Off: no cast bars, and the enemies sit closer together."] = "敌人施法时，在其条目下方显示带法术名称的细施法条；不可打断时，施法条变灰并显示护盾标记。关闭后隐藏施法条，敌人列表间距会缩小。",
    ["Letters on Name Plates"] = "姓名板字母标记",
    ["On: each row's letter (A, B, C...) also sits over that enemy's name plate, so you can tell which row is which. The letters are yours, not your party's."] = "在敌人姓名板上同步显示其在列表中的字母（A、B、C……），方便快速对应。标记只代表你自己的敌对列表，不代表队友的列表。",
    ["Name Plate Letter Size"] = "姓名板标记大小",
    ["How big the letter (or number) over each enemy's name plate is: 50% to 300%."] = "调整敌人姓名板上字母或编号的大小（50%–300%）。",
    ["Enemy List: Letters or Numbers"] = "敌人列表：字母或数字",
    ["Letters: A, B, C... on each row and over its name plate. Numbers: 1, 2, 3... instead."] = "字母模式：列表与姓名板使用 A、B、C……；数字模式改为 1、2、3……。",
    ["Letters"] = "字母",
    ["Enemy List: Your Target"] = "敌人列表：当前目标",
    ["Your target's edge: green low threat, yellow close to pulling, red you have aggro (Threat Color). Or your Class Color, Gold, or Off."] = "目标边框根据仇恨程度提示：绿色仇恨低，黄色接近拉怪，红色表示仇恨已转移到你；也可使用职业颜色、金色或关闭。",
    ["Threat Color"] = "仇恨颜色",
    ["Enemy List: Party Targets"] = "敌人列表：队友选中的目标",
    ["On: a diamond in each party member's class colour on every enemy they're fighting. On your target, a ring round each one who has it targeted too."] = "在每个队友正在攻击的敌人上显示该队友职业颜色的菱形标记。如果你也选中了此敌人，则在标记外附加圆环，用于区分队友目标。",
    ["Enemy List: Who It's Hitting"] = "敌人列表：正在攻击谁",
    ["On: an arrow past the frame in the colour of the party member it's hitting (none when it's you: the red square says so)."] = "敌人列表旁显示一个箭头，用被攻击队友的职业颜色标识目标。如果敌人正在攻击你，则不显示箭头，改用红色方框提示。",
    ["Missing Buffs"] = "缺少增益",
    ["Show Missing Buffs"] = "显示缺失的增益",
    ["On: a small row of icons for your own buffs, auras, seals, armors and weapon poisons - every one it watches, always: grayed while it's missing, bright while it's on you, with the time it has left (like your binds' numbers). Pick which in Missing Buffs: Watch. Buffs set to When Up (Show It) show on a line above it only while they're on you, with their time and stacks."] = "开启后，在屏幕显示一排个人增益监控图标，包括职业增益、光环、圣印、护甲效果与武器毒药。缺失时图标变灰；生效时图标高亮并显示剩余时间。可在“缺失增益 → 监控项目”中选择。设置为“生效时显示”的增益只会在身上有效时出现在监控栏上方，并显示持续时间和层数。",
    ["Missing Buffs: Watch"] = "缺失增益：监控项目",
    ["Left / right: your class's buffs and procs you know (a proc shows once you have its talent). A: watch it or not. At first your long self-buffs (a Paladin's aura and seal, a Mage's armor, a Rogue's poisons...); short buffs and procs - Righteous Fury, Slice and Dice, Clearcasting, Flurry, Vengeance... - are there to pick."] = "通过左右方向键浏览当前职业已学会的增益及触发效果（只有学到对应天赋才会出现）。按 A 决定是否监控。默认包括较长时间的自我增益，如圣骑士光环与圣印、法师护甲、盗贼毒药；也可监控正义之怒、切割、节能施法、乱舞、复仇等短时效果。",
    ["None for your class"] = "当前职业没有可用效果",
    ["Missing Buffs: In a Fight"] = "缺失增益：战斗时显示",
    ["Shown: the row stays in a fight too - grayed while a buff is missing, bright with its time left while it's on. Hidden: the row only shows out of a fight."] = "选择“显示”时，战斗中也保留监控栏：缺失的增益显示为灰色，生效的增益显示为高亮并标注剩余时间。选择“隐藏”时，仅在非战斗状态显示该栏。",
    ["Missing Buffs: Show It"] = "缺失增益：显示方式",
    ["For the buff picked in Watch. In the Row: it always shows in the row - grayed while it's missing, bright with its time left while it's on. When Up: it shows only while it IS on you, on a line just above the row, with the time it has left and its stacks - a proc (Clearcasting, Flurry, Vengeance...) flashes gold as it comes. Both work in a fight. A or left / right: switch."] = "针对当前选中的增益，选择显示方式。“常驻监控栏”：图标始终显示，缺失时灰色、生效时高亮并标注剩余时间。“仅生效时”：只在增益有效期间显示在监控栏上方，并标注持续时间与层数；节能施法、乱舞、复仇等触发效果出现时会短暂金色闪烁。两种模式均适用于战斗。按 A 或左右方向键切换。",
    ["Missing Buffs: Place"] = "缺失增益：显示位置",
    ["Its Own Spot: where you put it in Edit Layout (as before). Above / Below the Cooldown Manager: it sits against the game's Cooldown Manager (its main row of spells) whenever that shows - Edit Layout moves it from there - and back in its own spot while the Cooldown Manager is hidden."] = "“独立位置”：使用你在编辑布局中指定的地方。“冷却管理器上方／下方”：游戏原生冷却管理器显示时，将监控栏贴靠在其主技能行旁边；可在编辑布局中调整。冷却管理器隐藏时，监控栏返回自己的独立位置。",
    ["Wheels"] = "快捷轮盘",
    ["Wheel"] = "轮盘",
    ["Which wheel the other rows here change. All Wheels changes every wheel. Y: this wheel back to how it came."] = "选择下面设置要调整的轮盘；选“全部轮盘”可统一修改。按 Y 将当前轮盘恢复默认。",
    ["All Wheels"] = "全部轮盘",
    ["Reset"] = "重置",
    ["Rename This Wheel"] = "重命名此轮盘",
    ["A: type a new name for this Custom Wheel."] = "按 A 为此自定义轮盘输入新名称。",
    ["Custom Wheels Only"] = "仅自定义轮盘",
    ["Color"] = "颜色",
    ["The wheel's colour: Default, a class colour, or a plain colour."] = "选择轮盘颜色：默认、职业颜色或自定义纯色。",
    ["Texture"] = "纹理",
    ["What the wheel is made of: Marbled, Smooth, Glass, Stone, Neon and more."] = "选择轮盘材质：大理石、平滑、玻璃、石质、霓虹等。",
    ["Marbled"] = "大理石纹",
    ["Round, Square, Hexagon, Octagon, Flower or Gear."] = "圆形、方形、六角形、八角形、花朵或齿轮。",
    ["Round"] = "圆形",
    ["Wheel Icon"] = "轮盘图标",
    ["The picture this Custom Wheel shows on the button you put it on. A: pick one from the game's macro icons."] = "设置自定义轮盘在动作按钮上显示的图标。按 A 从游戏宏图标中选择。",
    ["Show A / B Hints"] = "显示 A / B 提示",
    ["On: a line by the wheel saying what A and B do."] = "在轮盘旁显示 A、B 键的操作提示。",
    ["Wheels Ignore the Mouse"] = "轮盘忽略鼠标",
    ["On: while a wheel is open, the camera holds still for mouse, trackpad and gyro. Holding a mouse button still turns it."] = "轮盘打开时，鼠标、触控板和体感输入不会改变镜头方向；按住鼠标键仍可转动镜头。",
    ["Pick With"] = "轮盘选择操作",
    ["Every wheel. Release: point a stick and let go to pick (A works too). A: the stick only points; A picks."] = "所有轮盘通用：选择“松开”，摇杆指向后松手确认（也可按 A）；选择“A”，则摇杆只移动选项，由 A 确认。",
    ["Release"] = "松开按键",
    ["Target Tooltip"] = "目标提示框",
    ["On: targeting something shows its tooltip. Show For sets how long."] = "选中单位或物体时显示提示框，持续时长由下方设置控制。",
    ["Target Tooltip: Show For"] = "目标提示框持续时间",
    ["How long the tooltip stays."] = "设置目标提示框持续显示的时间。",
    ["Cooldown, glow, range, mana"] = "冷却、高亮、距离与法力",
    ["Other modifiers' cooldowns"] = "其他组合键层的冷却时间",
    ["Melee swing timer"] = "近战自动攻击计时",
    ["Style, colour and size"] = "样式、颜色和大小",
    ["Marks round your target"] = "目标周围的标记",
    ["Enemies your group is fighting"] = "队伍正在交战的敌人",
    ["Your buffs that aren't on you"] = "自身缺失的增益",
    ["How the wheels look and work"] = "轮盘外观和操作方式",
    ["What shows for your target"] = "目标信息显示",
    ["Numbers and gray on your buttons while they cool down."] = "技能冷却时在按钮上显示剩余时间并置灰。",
    ["Glows"] = "高亮效果",
    ["Glows on your buttons: procs and interrupts."] = "技能触发效果与打断提示的按钮高亮。",
    ["Numbers"] = "数字",
    ["Number Size"] = "数字大小",
    ["Gray on Cooldown"] = "冷却时置灰",
    ["Range and Mana"] = "距离与法力",
    ["How a spell out of range or short of mana looks."] = "设置技能超出距离或法力不足时的按钮提示效果。",
    ["Out of Range"] = "超出范围",
    ["Range Color"] = "距离提示颜色",
    ["Low Mana Color"] = "法力不足提示颜色",
    ["What It Shows"] = "显示什么",
    ["Cooldowns on modifiers you aren't holding."] = "显示当前未按住的其他组合键层的技能冷却。",
    ["When it shows, and the parts on it."] = "设置显示时机与内容。",
    ["CF Look"] = "CF 外观",
    ["Out of Combat"] = "非战斗状态",
    ["Time Left"] = "剩余时间",
    ["Ammo Count"] = "弹药数",
    ["Label"] = "标签",
    ["Spark"] = "火花",
    ["Your swing timer is hidden in the game's Edit Mode. To see it in play: Edit Mode > Swing Timer > Visibility: Always or In Combat."] = "当前游戏编辑模式中隐藏了自动攻击计时条。如需显示，请进入“编辑模式 → 自动攻击计时条 → 可见性”，选择“始终”或“战斗中”。",
    ["The mark in the middle of the screen."] = "屏幕中间的标记。",
    ["Brackets"] = "目标边框",
    ["Marks round your target. Needs nameplates on."] = "在目标周围显示标记，需要开启姓名板。",
    ["Show Brackets"] = "显示目标边框",
    ["List"] = "列表",
    ["Enemies your group is fighting. Needs enemy name plates."] = "显示小队正在交战的敌人，需要启用敌方姓名板。",
    ["Your own buffs that aren't on you right now - and the buffs and procs you want to see while they're up."] = "监控自己身上缺失的增益，以及希望在触发或生效期间持续显示的增益。",
    ["Which Wheel"] = "选择轮盘",
    ["The wheel the card changes. Edit Layout: where it opens and how big."] = "选择要修改的轮盘；位置和大小在“编辑布局”中调整。",
    ["What it's made of, and the A / B line by it."] = "设置轮盘材质，以及旁边的 A／B 按键提示。",
    ["A / B Hints"] = "A／B 按键提示",
    ["Camera While Open"] = "轮盘打开时的镜头行为",
    ["The camera with any wheel open (every wheel, not just the one picked)."] = "设置打开任意轮盘时的镜头行为，适用于所有轮盘。",
    ["Picking"] = "选择方式",
    ["Ignore the Mouse"] = "忽略鼠标输入",
    ["How a pick is made, on every wheel (not just the one picked)."] = "设置轮盘如何确认选择，适用于全部轮盘。",
    ["Tooltip"] = "工具提示",
    ["Your target's tooltip for a few seconds."] = "显示当前目标的提示框，持续数秒。",
    ["Show Tooltip"] = "显示工具提示",
    ["Edit Layout for your whole layout, how it moves your buttons, and their shape."] = "调整整个手柄界面的布局、按键位置与形状。",
    ["Their symbols, and Edit Layout for the D-pad, A / B / X / Y or one button."] = "设置按键符号，并分别调整十字方向键、A／B／X／Y 或单个按钮的布局。",
    ["Triggers and Targeting"] = "扳机键与目标选择",
    ["Targeting Method, Tab Targeting, Stick Targeting and the LT / RT target icons."] = "设置目标选择方式、Tab 切换目标、摇杆选目标以及 LT／RT 目标图标。",
    ["Long Press"] = "长按",
    ["Long Press (Experimental)"] = "长按操作（实验性）",
    ["Hold A B X Y for a second bind. Experimental: A / B / X / Y only for now."] = "长按 A／B／X／Y 可触发第二个绑定动作。实验性功能，目前仅支持这四个按键。",
    ["Extra Bars"] = "额外动作条",
    ["Big buttons to tap at the edges of the screen (or in a row): how many, where, and what each casts."] = "在屏幕两侧或成排显示可点击的大型动作按钮，设置数量、位置和施放技能。",
    ["Size and place your buttons"] = "调整按键大小和位置",
    ["Symbols and Edit Layout"] = "按键符号与布局编辑",
    ["How you target, taps and holds"] = "目标选择、短按与长按",
    ["LB / RB as your own buttons"] = "将 LB／RB 设为独立按键",
    ["L3 / R3 as your own buttons"] = "将 L3／R3 设为独立按键",
    ["Bind Start"] = "绑定 Start 键",
    ["Bind Select"] = "绑定 Select 键",
    ["A button of your own"] = "自定义独立按键",
    ["Paddles and extra buttons"] = "背键与扩展键",
    ["Big buttons to tap at the edges"] = "屏幕边缘快捷按钮",
    ["Camera"] = "镜头",
    ["CF Camera View"] = "CF 自定义镜头",
    ["On: one of Controller Forever's camera views (the row below). Off: the game's own camera. Experimental."] = "开启后使用下方选择的 CF 镜头模式；关闭后使用游戏原生镜头（实验性）。",
    ["Camera View"] = "镜头视角",
    ["Over Right Shoulder, Over Left Shoulder, or Action Cam. Experimental."] = "可选右肩视角、左肩视角或动作镜头（实验性）。",
    ["Shoulder Distance"] = "镜头肩部偏移距离",
    ["How far over the shoulder the camera sits. Experimental."] = "调整镜头相对角色肩膀的水平偏移量（实验性）。",
    ["Vertical Pitch"] = "镜头垂直倾角",
    ["With a camera view on: 0 to 1, higher puts your character lower on the screen so you see more ahead. Game's: as the view comes. Experimental."] = "启用自定义镜头视角后，可在 0–1 范围调整镜头俯仰。数值越高，角色在画面中越靠下，前方可见区域越大。选择“游戏原生”则使用默认镜头表现（实验性）。",
    ["Zoom Out Distance"] = "镜头拉远距离",
    ["Far: zoom out farther than the game allows. Experimental."] = "“远”模式允许镜头拉得更远（实验性）。",
    ["Head Movement"] = "跑动时镜头随动",
    ["The view moves a little with your head as you run. Experimental."] = "奔跑时镜头会轻微跟随角色头部运动（实验性）。",
    ["Turn Toward Target"] = "镜头缓慢转向目标",
    ["The camera eases round toward your target. Experimental."] = "镜头会平滑地朝向当前目标旋转（实验性）。",
    ["Indoors"] = "室内",
    ["Calmer: the game's own camera inside buildings and caves. Experimental."] = "“更平稳”模式会在建筑及洞穴内使用游戏原生镜头（实验性）。",
    ["Calmer"] = "更平稳",
    ["Combat Zoom"] = "战斗时镜头缩放",
    ["As a fight starts: In comes closer (an enemy targeted), Out goes out to Combat Distance, Set Distances goes to Combat Distance. After it: back where you had it (Set Distances: to Out of Combat Distance). Experimental."] = "进入战斗时：“拉近”在选中敌人后靠近角色；“拉远”使用设定的战斗镜头距离；“指定距离”也切换至战斗距离。脱战后恢复进入战斗前的镜头距离（指定距离模式则切换到非战斗距离）。实验性功能。",
    ["Combat Distance"] = "战斗时镜头距离",
    ["With Combat Zoom Out or Set Distances: how far the camera sits in a fight, in yards. Experimental."] = "选择战斗镜头拉远或指定距离后，在此设置战斗时镜头距离（码，实验性）。",
    ["Out of Combat Distance"] = "非战斗时镜头距离",
    ["With Combat Zoom Set Distances: how far the camera sits after a fight, in yards. Experimental."] = "使用“指定镜头距离”时，设置脱战后的镜头距离（码，实验性）。",
    ["Vibration"] = "手柄震动",
    ["On: the controller vibrates for the things below that are on."] = "开启后，在下方已启用的事件发生时提供手柄震动反馈。",
    ["Strength"] = "震动强度",
    ["How strong every vibration is."] = "调整全部震动反馈的强度。",
    ["Test Vibration"] = "测试手柄震动",
    ["A few vibrations, to feel the strength."] = "播放几次短震动，测试当前强度。",
    ["Test"] = "测试",
    ["What Vibrates"] = "震动触发条件",
    ["Ability Used"] = "施放技能",
    ["A light tap when you use an ability. A turns it on or off; D-pad left / right: how strong."] = "使用技能时触发轻微震动。按 A 开关，方向键左右调整强度。",
    ["Cast Finished"] = "施法完成",
    ["A pulse when a cast finishes. A turns it on or off; D-pad left / right: how strong."] = "完成施法时触发短震动。按 A 开关，方向键左右调整强度。",
    ["While Casting"] = "施法过程中",
    ["A soft rumble while you cast. A turns it on or off; D-pad left / right: how strong."] = "施法过程中持续轻微震动。按 A 开关，方向键左右调整强度。",
    ["Cast Interrupted"] = "施法中断",
    ["A sharp jolt when a cast is interrupted. A turns it on or off; D-pad left / right: how strong."] = "施法被打断时触发明显震动。按 A 开关，方向键左右调整强度。",
    ["Hit Taken"] = "受到攻击",
    ["A tap each time you are hit. A turns it on or off; D-pad left / right: how strong."] = "每次受到攻击时触发轻微震动。按 A 开关，方向键左右调整强度。",
    ["Big Hit Taken"] = "受到暴击",
    ["A jolt on a critical hit. A turns it on or off; D-pad left / right: how strong."] = "受到暴击时触发明显震动。按 A 开关，方向键左右调整强度。",
    ["Entering Combat"] = "进入战斗",
    ["A pulse when a fight starts. A turns it on or off; D-pad left / right: how strong."] = "进入战斗时触发短震动。按 A 开关，方向键左右调整强度。",
    ["Leaving Combat"] = "离开战斗",
    ["A tap when a fight ends. A turns it on or off; D-pad left / right: how strong."] = "脱离战斗时触发轻微震动。按 A 开关，方向键左右调整强度。",
    ["Jump"] = "跳跃",
    ["A tap when you jump. A turns it on or off; D-pad left / right: how strong."] = "跳跃时触发轻微震动。按 A 开关，方向键左右调整强度。",
    ["Mounting"] = "骑乘坐骑",
    ["A pulse when you mount. A turns it on or off; D-pad left / right: how strong."] = "骑乘坐骑时触发短震动。按 A 开关，方向键左右调整强度。",
    ["Whisper Received"] = "收到密语",
    ["A pulse when someone whispers you. A turns it on or off; D-pad left / right: how strong."] = "收到密语时触发短震动。按 A 开关，方向键左右调整强度。",
    ["Fish Hooked"] = "鱼上钩",
    ["A jolt when you hook a fish. A turns it on or off; D-pad left / right: how strong."] = "鱼上钩时触发震动。按 A 开关，方向键左右调整强度。",
    ["Dialogue"] = "对话界面",
    ["Off: the game's window. Box: a box of ours with their face and words. Banner: the UI fades out, a band at the bottom with your faction's banners. Cinematic: the UI fades out, a band at the bottom."] = "对话窗口样式：关闭＝游戏原生窗口；方框＝显示 NPC 肖像和对白的 CF 对话框；阵营横幅＝界面淡出，在底部显示带阵营旗帜的对白条；电影式＝界面淡出，仅保留底部对白条。",
    ["Cinematic"] = "电影式对话",
    ["Close-Up When Talking"] = "交谈时镜头特写",
    ["The camera comes in close while you talk to anyone. Out of a fight."] = "脱离战斗后，与 NPC 交谈时镜头拉近。",
    ["Talking Close-Up Angle"] = "交谈特写角度",
    ["From the Side, From in Front, or From Behind. Out of a fight."] = "脱战时的交谈特写可以从侧面、正面或背面拍摄。",
    ["From the Side"] = "侧面",
    ["Slow Turn While Talking"] = "交谈时缓慢环绕",
    ["With the talking close-up: the camera slowly circles round while you talk. Out of a fight."] = "开启交谈特写后，脱战期间镜头缓慢围绕角色旋转。",
    ["Slow Turn Direction"] = "环绕方向",
    ["Which way the slow turn goes round. Out of a fight."] = "选择脱战交谈时镜头缓慢旋转的方向。",
    ["Where it sits and how it moves"] = "镜头位置与移动",
    ["On or off, and how strong"] = "启用状态与强度",
    ["Talking to NPCs, close-ups"] = "NPC 对话与镜头特写",
    ["View"] = "视角",
    ["Where the camera sits."] = "调整镜头位置。",
    ["Motion"] = "镜头运动",
    ["How it moves on its own."] = "调整镜头自动移动效果。",
    ["CF View"] = "CF 镜头",
    ["Zoom Out"] = "缩小",
    ["Turn to Target"] = "转向目标",
    ["Where the camera goes as a fight starts and ends."] = "控制进入战斗和脱离战斗时的镜头变化。",
    ["The window when you talk to someone."] = "与 NPC 交谈时显示的窗口。",
    ["The close-up while you talk. Out of a fight."] = "脱战时交谈镜头特写。",
    ["Close-Up"] = "特写",
    ["Left / right: Compact (one bar of buttons, changing as you hold LT / RT), Final Fantasy (every modifier's bar at once) or Trigger Bar (all four side by side in one bar). The layout's own settings are under it."] = "左右方向键选择布局：紧凑（同一动作条随 LT／RT 切换）、FF 风格（各组合键动作条同时显示）、扳机动作条（四组按键横向排列）。详细布局设置位于下方。",
    ["The camera comes in close while you talk to anyone."] = "当您与任何人交谈时，摄像机会靠近。",
    ["Move every part of your screen with the controller. D-pad moves, LB / RB next part, LT / RT size, B done."] = "通过手柄编辑界面：十字方向键移动，LB／RB 切换调整区域，LT／RT 缩放，按 B 完成。",
    ["Edit Layout Grid"] = "编辑布局网格",
    ["The lines behind Edit Layout. Off for a clear screen. Select switches it in Edit Layout too."] = "控制编辑布局时是否显示辅助网格；关闭可获得更清爽的视图。布局编辑界面也可按 Select 切换。",
    ["Move every part of your screen with the controller."] = "使用手柄移动各个界面元素。",
    ["Grid"] = "网格",
    ["Spells"] = "法术",
    ["Auto-Place Spells"] = "自动放置技能",
    ["Fill Empty Buttons Now"] = "立即填充空按钮",
    ["Runs Auto-Place Spells once, right now."] = "立即执行一次技能自动放置。",
    ["Remove Placed Spells"] = "清除自动放置的技能",
    ["Takes off every spell Auto-Place Spells placed. Yours stay."] = "移除插件自动添加的技能，保留你手动绑定的技能。",
    ["Update to New Spell Ranks"] = "自动更新到新法术等级",
    ["On (the default): a new rank you learn replaces the old one on every button. Experimental."] = "开启（默认）后，学习更高等级的技能时自动替换各按键上的旧等级技能。实验性功能。",
    ["Item Pickers"] = "物品选择器",
    ["Item Picker (Enchants, Poisons, Stones)"] = "物品选择器（附魔、毒药、石头）",
    ["When a spell waits for you to pick an item (enchants, Disenchant, sharpening stones, poisons, Pick Lock), a list of the items it can go on comes up: D-pad picks, A puts it on, B cancels. Out of a fight."] = "当附魔、分解、磨刀石、毒药、开锁等技能需要选定物品时，插件会列出可用目标。十字方向键选择，按 A 使用，按 B 取消。仅脱战时可操作。",
    ["Disenchant Picker"] = "装备分解选择器",
    ["Lists the green, blue and purple gear in your bags: pick one with the D-pad, A asks, A again disenchants it. Also on any button: All Keybinds > Game Actions > Disenchant."] = "列出背包中绿色、蓝色和紫色品质的装备。通过方向键选中，第一次按 A 显示确认，再按 A 执行分解。也可在“全部按键绑定 → 游戏操作 → 分解”中单独绑定。",
    ["Disenchant: Keep Going"] = "分解后继续",
    ["On: after you disenchant an item from the Mini Bag it stays open with the gear you can still disenchant, so A goes straight on to the next one. B closes it; it also closes when nothing is left, a fight starts, you walk off or cast something else. Off: it closes after each disenchant."] = "开启后，从迷你背包分解一件物品后列表不会立即关闭，可以继续选择下一件并按 A 分解。按 B 关闭；当没有可分解物品、进入战斗、离开操作位置或施放其他技能时也会关闭。关闭本选项则每分解一次就自动关闭。",
    ["One-Press Disenchant"] = "一键分解",
    ["On: in the Mini Bag one A disenchants the lit item at once. A disenchanted item can't be got back. Off: A asks first, A again disenchants."] = "开启后，在迷你背包中对高亮物品按一次 A 就会立即分解，分解后无法找回！关闭后第一次按 A 显示确认，第二次按 A 才执行分解。",
    ["Keep Going"] = "继续",
    ["One-Press"] = "单按操作",
    ["Disenchanting..."] = "正在分解…",
    ["Nothing left to disenchant."] = "没有可继续分解的物品。",
    ["Tracking List"] = "附近目标追踪列表",
    ["Open the Tracking List"] = "打开追踪列表",
    ["A list beside the minimap of what's around you (flight masters, quest givers, rares...): pick one and a ring shows where it is. Also a bind: Windows > Tracking List."] = "小地图旁显示附近目标列表，例如飞行管理员、任务 NPC 和稀有怪。选中某项后，小地图会出现圆环指示其位置。也可从“窗口 → 追踪列表”绑定快捷键。",
    ["Closed"] = "已关闭",
    ["Tracking List Button"] = "追踪列表按钮",
    ["On: a small button on the minimap opens the list."] = "开启：小地图上的小按钮可打开列表。",
    ["Tracking List Shows"] = "追踪列表显示范围",
    ["Nearby: only what is in the minimap's view. Whole Zone: everything on the map."] = "附近：只显示小地图范围内的目标。整个区域：显示世界地图上的全部相关目标。",
    ["Nearby"] = "附近",
    ["Mark the Pick on the Minimap"] = "在小地图标记所选目标",
    ["On: a ring on the minimap shows where the row you pick is."] = "开启后，小地图上用圆环标出追踪列表当前选中的目标。",
    ["Your spells on your buttons."] = "查看绑定在动作按钮上的技能。",
    ["Enchants, poisons, stones and other spells that go on an item, picked with the controller."] = "使用手柄选择附魔、毒药、磨刀石等需要指定物品的技能或道具。",
    ["Auto-Place"] = "自动放置",
