    ["Binds"] = "绑定",
    ["Choose Extra Bar Spells"] = "设置额外动作条技能",
    ["All Keybinds on its Extra Bars page: pick a button, A for the spell list, or drop a spell on it."] = "在“全部按键绑定 → 额外动作条”中选中按键，按 A 打开技能列表，或直接拖入技能。",
    ["Bind Controller Buttons"] = "绑定手柄按键",
    ["Give each Extra Bar button a spare button or key: A, then press one for each in turn (A skips, B stops)."] = "为额外动作条的每个按钮设置空闲按键：按 A 开始，依次按要绑定的键。A 跳过，B 结束。",
    ["None"] = "无",
    ["Clear Controller Buttons"] = "清除手柄按键绑定",
    ["Takes the controller buttons and keys off every Extra Bar button. What they cast stays."] = "清除额外动作条上的按键绑定，保留对应技能。",
    ["Show Button Names"] = "显示按钮名称",
    ["Shown: each Extra Bar button shows the controller button or key it's bound to along its top. Hidden: no words."] = "开启后，额外动作条的每个按钮上方会显示对应的手柄／键盘快捷键；隐藏后不显示文字。",
    ["Reset Extra Bars"] = "重置额外动作条",
    ["Every bar back where it started (the left and right ones the middle of their edge), at the size they started."] = "将额外动作条恢复到默认位置和大小：左、右动作条分别回到屏幕两侧中央。",
