    ["Edit Layout: A"] = "编辑布局：A",
    ["Edit Layout: B"] = "编辑布局：B",
    ["Edit Layout: X"] = "编辑布局：X",
    ["Edit Layout: Y"] = "编辑布局：Y",
    ["Controller Icons"] = "手柄按键图标",
    ["Auto reads your controller, or pick Xbox, PlayStation or Nintendo. Hidden: none on your buttons on screen; menus still show them."] = "自动识别手柄类型，或手动选择 Xbox、PlayStation、Nintendo。选择隐藏后，游戏动作按钮不显示图标，但设置菜单仍会显示。",
    ["Controller Icon Style"] = "手柄图标样式",
    ["Bold Light / Bold Dark: just the letters and shapes, nothing round them - white and light colours, or charcoal and the controllers' own colours. Basic: flat. Detailed: CF's stone buttons. Game's Own: the game's pictures."] = "“醒目浅色／深色”：只显示按键字母与形状，不绘制外框；分别采用浅色系，或深灰加手柄品牌配色。“基础”：扁平图标。“详细”：CF 石质按钮。“游戏原生”：使用游戏自带按键图案。",
    ["Bold Light"] = "浅色醒目样式",
    ["Icon Size in Text"] = "文字中的图标大小",
    ["Size of the controller icons in text: Small, Medium, Large or Huge."] = "选择文字旁手柄图标的尺寸：小、中、大或特大。",
    ["Small"] = "小号",
    ["Icon Position"] = "图标位置",
    ["Where the icon sits on your buttons: a side, a corner or the middle. Default: top right, as it always was."] = "设置图标显示在按钮边缘、角落或中央。默认位于右上角。",
    ["Icon Placement"] = "图标摆放方式",
    ["Inside the button, hanging Outside it, or in the Middle of its edge."] = "图标可显示在按钮内部、按钮外侧或边缘中间。",
    ["Inside"] = "内侧",
    ["Size of the icons on A / B / X / Y and the D-pad."] = "调整 A／B／X／Y 和十字方向键上的按键图标大小。",
    ["Other Buttons Icon Size"] = "其他按键图标大小",
    ["Size of the icon on LB / RB, L3 / R3, Start, Select, Xbox and the back buttons. 21 is normal."] = "设置 LB／RB、L3／R3、Start、Select、主机键与背键的图标大小；21 为常规大小。",
    ["Edit Layout moves and sizes the whole D-pad, or one arrow."] = "编辑布局可调整整个十字方向键或单个方向按钮的位置和大小。",
    ["Edit Layout moves and sizes A / B / X / Y together, or one of them."] = "编辑布局可同时调整 A／B／X／Y 四键，或只调整其中一个。",
    ["Edit Layout: All"] = "编辑布局：全部",
    ["Edit Layout: Up"] = "编辑布局：上",
    ["Edit Layout: Down"] = "编辑布局：下",
    ["Edit Layout: Left"] = "编辑布局：左",
    ["Edit Layout: Right"] = "编辑布局：右",
    ["The controller icons on your buttons and in text."] = "设置动作按钮及菜单文字中的手柄图标。",
