    ["All Buttons"] = "所有按钮",
    ["Set All at Once"] = "一键统一设置",
    ["One press sets every switch below: In Combat, Hostile Target or Off."] = "按一次为下方所有按键选择切换条件：战斗中、选中敌对目标或关闭。",
    ["Every Modifier"] = "所有组合键",
    ["A second set of A / B / X / Y binds for a fight or a hostile target. Bind it: All Keybinds, L3."] = "进入战斗或选中敌对目标时，可为 A／B／X／Y 切换第二套按键配置。到「全部按键绑定 → L3」设置。",
    ["In Combat"] = "战斗中",
    ["D-pad Use a Combat Set"] = "方向键使用战斗按键组",
    ["A second D-pad set for a fight or a hostile target. Bind it: All Keybinds, L3."] = "在战斗中或选中敌人时切换第二套方向键绑定，可在“全部按键绑定 → L3”中设置。",
    ["LB / RB Use a Combat Set"] = "LB／RB 使用战斗按键组",
    ["A second LB / RB set for a fight or a hostile target. Bind it: All Keybinds, L3."] = "在战斗中或选中敌人时启用第二套 LB／RB 绑定；设置入口为“全部按键绑定 → L3”。",
    ["L3 / R3 Use a Combat Set"] = "L3／R3 使用战斗按键组",
    ["A second L3 / R3 set for a fight or a hostile target. Bind it: All Keybinds, L3."] = "在战斗中或选中敌人时启用第二套 L3／R3 绑定；设置入口为“全部按键绑定 → L3”。",
    ["Start Use a Combat Set"] = "Start 使用战斗按键组",
    ["A second Start set for a fight or a hostile target. Bind it: All Keybinds, L3."] = "在战斗中或选中敌人时启用第二套 Start 按键绑定；设置入口为“全部按键绑定 → L3”。",
    ["Select Use a Combat Set"] = "Select 使用战斗按键组",
    ["A second Select set for a fight or a hostile target. Bind it: All Keybinds, L3."] = "在战斗中或选中敌人时启用第二套 Select 按键绑定；设置入口为“全部按键绑定 → L3”。",
    ["L4 / R4 Use a Combat Set"] = "L4／R4 使用战斗按键组",
    ["A second L4 / R4 set for a fight or a hostile target. Bind it: All Keybinds, L3."] = "在战斗中或选中敌人时启用第二套 L4／R4 背键绑定；设置入口为“全部按键绑定 → L3”。",
    ["L5 / R5 Use a Combat Set"] = "L5／R5 使用战斗按键组",
    ["A second L5 / R5 set for a fight or a hostile target. Bind it: All Keybinds, L3."] = "在战斗中或选中敌人时启用第二套 L5／R5 背键绑定；设置入口为“全部按键绑定 → L3”。",
    ["Xbox Button Use a Combat Set"] = "主机键使用战斗按键组",
    ["A second Xbox button set for a fight or a hostile target. Bind it: All Keybinds, L3."] = "在战斗中或选中敌人时启用第二套主机键绑定；设置入口为“全部按键绑定 → L3”。",
    ["E1 - E4 Use a Combat Set"] = "E1–E4 使用战斗按键组",
    ["A second E1 - E4 set for a fight or a hostile target. Bind it: All Keybinds, L3."] = "在战斗中或选中敌人时启用第二套 E1–E4 扩展键绑定；设置入口为“全部按键绑定 → L3”。",
    ["Every button below at once."] = "下方所有按键统一设置。",
    ["Each button's combat set is used alone and with LT, RT, LT + RT. Bind it: All Keybinds, L3."] = "每个按键都有独立、LT、RT 及 LT＋RT 四组战斗绑定。可在「全部按键绑定 → L3」中设置。",
    ["LB / RB"] = "LB / RB",
    ["Start"] = "Start",
    ["Select"] = "Select",
