    ["Active"] = "当前启用",
    ["Edit Loadout 1 in All Keybinds"] = "在“全部按键绑定”中编辑配置方案 1",
    ["Makes this the loadout you're using (no question) and opens All Keybinds on it."] = "直接启用此配置方案，并在“全部按键绑定”中打开对应设置。",
