    ["Save My Gear Now for Loadout 5"] = "将当前装备保存到配置方案 5",
    ["Party Mode With Loadout 5"] = "配置方案 5 的队伍模式",
    ["Spec With Loadout 5"] = "配置方案 5 的天赋专精",
    ["Save My Gear Now for Loadout 6"] = "将当前装备保存到配置方案 6",
    ["Party Mode With Loadout 6"] = "配置方案 6 的队伍模式",
    ["Spec With Loadout 6"] = "配置方案 6 的天赋专精",
    ["Loadout 7"] = "配置方案 7",
    ["Save My Gear Now for Loadout 7"] = "将当前装备保存到配置方案 7",
    ["Party Mode With Loadout 7"] = "配置方案 7 的队伍模式",
    ["Spec With Loadout 7"] = "配置方案 7 的天赋专精",
    ["Save My Gear Now for Loadout 8"] = "将当前装备保存到配置方案 8",
    ["Party Mode With Loadout 8"] = "配置方案 8 的队伍模式",
    ["Spec With Loadout 8"] = "配置方案 8 的天赋专精",
    ["Settings"] = "设置",
    ["Loadouts Swap Gear"] = "切换配置方案时同时换装",
    ["On: each loadout remembers your gear and puts it back when you switch."] = "开启后，每个配置方案会保存自己的装备，切换方案时自动换装。",
    ["Show Loadout Name"] = "显示配置方案名称",
    ["On: the loadout's name and picture show in the middle of the screen when it switches."] = "切换配置方案时，在屏幕中央显示其名称与图标。",
    ["Follow My Spec"] = "按天赋专精自动切换配置方案",
    ["On: when you change spec another way (the talent window), the loadout that goes with it comes up."] = "开启后，通过天赋界面切换专精时，自动启用与该专精关联的配置方案。",
    ["Add / Remove Loadouts"] = "添加／移除配置方案",
    ["Add a Loadout"] = "添加配置方案",
    ["One more loadout, up to 8. Loadouts past the third switch out of a fight and take the bar page of the loadout you leave."] = "新增一个配置方案，最多 8 个。第 4 个及之后的方案需脱战切换，并沿用切换前方案的动作条页面。",
    ["3 loadouts"] = "3 个配置方案",
    ["Remove Last Loadout"] = "移除最后一个配置方案",
    ["Takes away the last loadout (not the one you're using). It's kept: Add a Loadout brings it back as it was."] = "移除最后一个配置方案（不能移除当前正在使用的方案）。内容会保留，再次添加时可恢复。",
    ["Show Other Sets"] = "查看其他配置方案",
    ["Three sets fit here at a time: this shows the next ones (1 - 3, 4 - 6, 7 - 8)."] = "每页显示 3 个配置方案，按此切换显示 1–3、4–6 或 7–8。",
    ["Each loadout's own gear."] = "为各配置方案分别保存装备。",
    ["Up to 8 loadouts, 3 to a card."] = "最多支持 8 个配置方案，每页显示 3 个。",
    ["Its own binds; the one you start with."] = "此配置方案独立保存按键绑定，并作为初始方案使用。",
    ["Its own binds."] = "此配置方案独立保存按键绑定。",
    ["Use This Loadout"] = "使用此配置方案",
    ["Edit in All Keybinds"] = "在所有按键绑定中编辑",
    ["Bind to a Button"] = "绑定到按钮",
    ["Save My Gear Now"] = "保存当前装备",
    ["Party Mode: Leave As Is"] = "队伍模式：保持当前设置",
    ["Spec: Don't Change"] = "天赋专精：保持不变",
    ["Clear"] = "清除",
    ["Swap Gear: On"] = "切换装备：开启",
    ["Show Loadout Name: On"] = "显示配置方案名称：开启",
    ["Follow My Spec: On"] = "跟随天赋专精：开启",
    ["Press Again Healing"] = "再次按键治疗",
    ["Healing Mode"] = "治疗模式",
    ["Aura Priority checks your own effects on the picked member on every press: your own buffs, not cooldowns, health, range or cast success (a shield can still fail while Weakened Soul is on). Missing rule 1 always takes priority again. Configure out of combat."] = "每次按键检查所选队友身上由你施加的效果。只检测你的增益／持续治疗效果，不检测技能冷却、血量、距离或施法成功。目标有「虚弱灵魂」时护盾仍可能施放失败。请脱战配置。",
    ["Single Heal"] = "单一治疗技能",
    ["First Heal"] = "优先治疗 1",
    ["Single Heal mode uses this spell. Aura Priority: apply this first if your effect is missing. Off disables Press Again."] = "单一治疗模式使用此技能；效果优先模式下，目标缺少该效果时优先尝试施放。关闭会禁用再次按键治疗。",
    ["Second Heal"] = "优先治疗 2",
    ["Aura Priority: cast this only when your earlier effects are present and this effect is missing. Choose a heal with a lasting buff, such as Regrowth or Renew; Off skips this rule."] = "效果优先模式下，前序效果已存在且目标缺少此持续治疗效果时才尝试施放；适合「恢复」等持续治疗技能。关闭可跳过该规则。",
    ["Third Heal"] = "优先治疗 3",
    ["Fallback Heal"] = "后备治疗技能",
    ["Cast this when all enabled effects above are present. Any helpful heal; Off means no additional cast."] = "当前面的持续效果均已存在时，尝试施放此后备治疗技能。可选任意可治疗友方的技能；关闭则不额外施放。",
    ["Party Mode"] = "队伍治疗模式",
    ["Bind Party Pick: 5 Buttons"] = "绑定 5 个队友选择键",
    ["Bind Target Self"] = "绑定目标：自己",
    ["Not bound"] = "未绑定",
    ["Bind Target Party Member 1"] = "绑定目标：队友 1",
    ["Bind Target Party Member 2"] = "绑定目标：队友 2",
    ["Bind Target Party Member 3"] = "绑定目标：队友 3",
    ["Bind Target Party Member 4"] = "绑定目标：队友 4",
    ["Press Again Casts"] = "再次按键施法",
    ["Choose a single heal or an aura priority: first missing heal-over-time or shield, then a fallback."] = "选择单一治疗技能，或优先补缺失的持续治疗／护盾效果，然后使用后备治疗。",
    ["Target Who You Pick"] = "选中轮盘选定的队友",
    ["Soft Targeting (the default): only your heals go to the one you pick, and your enemy target stays. Hard Targeting: picking someone makes them your real target too."] = "软目标模式（默认）：治疗会施放给你选中的队友，但当前敌对目标保持不变。硬目标模式：选择队友时，也会将其设为角色的正式目标。",
    ["Soft Targeting"] = "软目标选择",
    ["Combat Sets Out of a Fight"] = "非战斗时使用战斗按键组",
    ["With Party D-pad or 5 Buttons on. On: your combat sets work out of a fight too. Off: only in a fight, the same as with Party mode off."] = "启用方向键或五按键选队友模式时，可以选择非战斗状态也允许使用战斗按键组；关闭后仅在战斗中生效，与队伍模式关闭时一致。",
    ["Put Party D-pad on a Button"] = "将十字方向键选队友功能绑定到按键",
    ["Party Pick Buttons"] = "选择队友按键",
    ["Which four buttons pick: the D-pad, or A / B / X / Y."] = "选择哪组按键用来选队友：十字方向键或 A／B／X／Y。",
    ["Party Pick Modifier"] = "队友选择组合键",
    ["The modifier the Party Pick buttons are on. Off that modifier the buttons do their own binds."] = "设置队友选择按键所用的组合层。不在该组合层时，按键继续执行各自原有绑定。",
    ["None (Alone)"] = "无组合键（直接按）",
    ["Keep on Every Modifier"] = "在所有组合层生效",
    ["On: the Party Pick buttons pick on every modifier."] = "开启后，所有组合键层均可使用队友选择键。",
    ["2 Members + 2 Shortcuts"] = "2 名队友＋2 个快捷操作",
    ["On: two directions pick a member; the other two are the shortcuts below. Off: all four pick."] = "开启后，两个方向键用于选择队友，另外两个用于自定义快捷操作；关闭则四个方向键全部选队友。",
    ["First Shortcut"] = "第一个快捷操作",
    ["Focus, Self, Target of Target, or the button's own bind."] = "可选择焦点目标、自己、目标的目标，或该按键原有绑定。",
    ["Focus"] = "焦点目标",
    ["Second Shortcut"] = "第二个快捷操作",
    ["The same choices for the other spare direction."] = "为另一个空闲方向键选择相同类型的操作。",
    ["Self"] = "自己",
    ["Put Party Wheel on a Button"] = "将队友轮盘绑定到按键",
    ["Pressing this bind turns the Party Wheel on and off (in a fight: when the fight ends). Off: the wheel never opens, even on a spell."] = "按此快捷键开启或关闭队友轮盘；战斗中可能需要等脱战后完成开关。关闭后，即使使用友方技能也不会打开轮盘。",
    ["Open on a Friendly Spell"] = "施放友方技能时打开轮盘",
    ["On: a heal, cleanse or blessing with no friendly target opens the wheel. Point a stick at someone and let go: it's cast on them."] = "开启后，当治疗、驱散或祝福技能没有有效友方目标时会自动打开队友轮盘；摇杆指向队友并松开即可施法。",
    ["Party Wheel Heal"] = "轮盘治疗",
    ["The spell cast when you open the wheel with its own bind: point a stick at someone and let go. When a friendly spell opened it, that spell is cast instead. Left / right: pick another of your heals."] = "用轮盘专属快捷键打开轮盘时，将施放下方选中的治疗技能：摇杆指向队友后松开即可确认。如果轮盘是由某个友方技能打开，则优先施放那个技能。可用左右方向键切换轮盘默认治疗法术。",
    ["No heal known"] = "尚未学习治疗技能",
    ["Party Wheel Look"] = "队友轮盘外观",
    ["What the wheel is made of. Blizzard is the game's own wheel. Colour and shape: CF UI > Wheels, with the Party Wheel picked; its size: Edit Layout's Wheel part."] = "选择轮盘外观：暴雪原生轮盘或 CF 自定义轮盘。自定义轮盘的颜色与形状可在“CF 界面 → 轮盘”中调整，尺寸在“编辑布局 → 轮盘”中修改。",
    ["Stay Open After a Heal"] = "治疗后保持轮盘打开",
    ["On: letting go of the stick casts and the wheel stays up, so you can heal the next one. B closes it. Off at first."] = "开启后，松开摇杆即对选中队友施法，轮盘仍保持打开，以便继续治疗下一人；按 B 关闭。默认关闭。",
    ["Edit the Party Set"] = "编辑队伍治疗方案",
    ["Opens All Keybinds on your Party Set: its binds take over while a friend is your target. A button with nothing in it keeps its normal bind."] = "打开队伍按键方案的“全部按键绑定”：选中友方时使用队伍方案的绑定。队伍方案中未配置的按键继续执行原有功能。",
    ["Highlight / Cursor"] = "高亮／光标",
    ["Highlight Style"] = "高亮样式",
    ["How the one you picked is marked: Corners, Thick Ring, Glow, Crosshair or Cursor. With Cursor, its own rows show beside it."] = "可使用四角框、粗圆环、发光、准星或光标来标识选中的队友。光标模式还会在标记旁显示详细信息。",
    ["Corners"] = "四角框",
    ["Highlight Color"] = "高亮颜色",
    ["Its colour. Your focus target is always purple."] = "调整高亮颜色。焦点目标始终使用紫色。",
    ["Highlight Pulse"] = "高亮脉冲",
    ["On: the highlight breathes slowly. Off: it holds still."] = "开启时高亮效果缓慢呼吸闪烁；关闭则保持静止。",
    ["Cursor Spot"] = "光标位置",
    ["Cursor style: which side or corner of their frame the ring sits on."] = "光标样式：选择环形标记在队伍框体的哪一侧或哪一个角落显示。",
    ["Left"] = "左",
    ["Cursor Frame Border"] = "光标边框",
    ["Cursor style: the line round their frame. Thin, Thick, Glow, Corners or None."] = "设置队友框体周围的高亮线条：细、粗、发光、四角或不显示。",
    ["Thin"] = "薄",
    ["Cursor Fill"] = "施法进度填充",
    ["How your cast fills the ring: Fill Up, Empty Out, Ring Around, Rise From Bottom or Off."] = "设置施法进度在标记环中的显示方式：逐步填满、逐步清空、环形推进、从底部上升或关闭。",
    ["Fill Up"] = "逐步填满",
    ["Cursor Fill Color"] = "光标进度填充颜色",
    ["The fill's colour: the highlight's, or Gold, White, Blue, Red or Purple."] = "填充颜色：突出显示的颜色，或金色、白色、蓝色、红色或紫色。",
    ["Match Highlight"] = "跟随高亮颜色",
    ["Cursor Shows Your Cast"] = "光标显示正在施放的技能",
    ["Cursor style: on, the spell you're casting shows inside it. Off: the heal picture stays."] = "开启时，队伍光标中显示当前施放的技能；关闭则持续显示治疗图标。",
    ["Buff Radar"] = "增益监控",
    ["On: each press of its bind buffs the next player near you who needs your buff. In a fight it goes down the list made when the fight began."] = "开启：每次按下绑定都会为您附近需要您的增益的下一个玩家提供增益。在一场战斗中，它会按照战斗开始时制定的清单进行。",
    ["Buff Radar on Screen"] = "在屏幕显示增益监控",
    ["A small line beside your party frames: how many need your buff and who's next. It flashes when someone new needs it. Move it in Edit Layout."] = "在你的队伍框架旁边有一条小线：有多少人需要你的增益以及下一个是谁。当新人需要它时它会闪烁。将其移动到编辑布局中。",
    ["Buff Radar: Buff"] = "增益监控：技能",
    ["Which of your buffs it casts, the highest rank you know. All My Buffs (last): each press gives the next buff someone's missing - everyone's first buff before the next - as Who Gets Each Buff says."] = "选择需要施放的增益法术，插件会使用已学会的最高等级。“我的全部增益”（最后一项）模式下，每次按键依次为缺少增益的队友施放下一个技能；先处理全队的第一个增益，再继续下一种。适用对象由“各增益施放对象”设置决定。",
    ["Mark of the Wild (not learned)"] = "野性印记（未学过）",
    ["Buff Radar: Rebuff Under"] = "增益监控：少于该时长补增益",
    ["Someone whose buff has less time left than this gets it again (up to 60 min; never one you just cast)."] = "当队友的增益剩余时间低于指定阈值时，允许重新施放（阈值最高 60 分钟；不会马上重复刚施放的增益）。",
    ["5 min"] = "5 分钟",
    ["Glow Its Button"] = "高亮对应按钮",
    ["On: the bar button with a Buff Radar bind glows while someone near you needs its buff."] = "开启：当您附近的人需要其增益时，带有增益雷达绑定的栏按钮会发光。",
    ["Put Buff Radar on a Button"] = "将增益监控绑定到按键",
    ["Press the button you want Buff Radar on. It's also in All Keybinds, Game Actions."] = "按您想要打开增益雷达的按钮。它也位于所有按键绑定、游戏操作中。",
    ["Buff Radar 2"] = "增益监控 2",
    ["On: a bind of its own buffs the next player near you who needs the buff picked below, as Buff Radar does with its own. In a fight too. Off at first."] = "开启后，可用一个独立快捷键自动选择附近下一名需要指定增益的队友，并尝试为其施放；与增益监控功能配合使用，战斗中也能触发。默认关闭。",
    ["Buff Radar 2 on Screen"] = "在屏幕显示增益监控 2",
    ["A small line of its own, under Buff Radar's: how many need its buff and who's next. Move it in Edit Layout."] = "在增益雷达下方有一条自己的小线：有多少人需要它的增益以及下一个是谁。将其移动到编辑布局中。",
    ["Buff Radar 2: Buff"] = "增益监控 2：技能",
    ["Which of your buffs it casts, the highest rank you know. Who gets it: Who Gets Each Buff."] = "选择需要施放的增益法术，插件会使用已学会的最高等级。“我的全部增益”（最后一项）模式下，每次按键依次为缺少增益的队友施放下一个技能；先处理全队的第一个增益，再继续下一种。适用对象由“各增益施放对象”设置决定。",
    ["Thorns (not learned)"] = "荆棘（没学过）",
    ["Put Buff Radar 2 on a Button"] = "将增益监控 2 绑定到按键",
    ["Buff Radar 3"] = "增益监控 3",
    ["Buff Radar 3 on Screen"] = "在屏幕显示增益监控 3",
    ["Buff Radar 3: Buff"] = "增益监控 3：技能",
    ["Put Buff Radar 3 on a Button"] = "将增益监控 3 绑定到按键",
    ["Who Gets Mark of the Wild"] = "野性印记施放对象",
    ["Everyone"] = "所有队友",
    ["Who Gets Thorns"] = "荆棘术施放对象",
    ["Tanks"] = "坦克",
    ["Dispel Radar"] = "驱散监控",
    ["On: each press of its bind removes a debuff from the next player near you who has one you can remove. In a fight: whoever in your party has one, then you, then your friendly target (in a raid: your own group of five)."] = "每次按绑定键都会尝试驱散附近下一名符合条件的队友。战斗中优先处理小队内可驱散目标，再考虑自己及当前友方目标；团队环境中优先当前五人小队。",
    ["Dispel Radar on Screen"] = "在屏幕显示驱散监控",
    ["A small line under Buff Radar's: how many need a dispel and who's next, in the debuff's colour. Move it in Edit Layout."] = "Buff 雷达下方的一条小线：有多少人需要驱散，下一个是谁，以减益的颜色显示。将其移动到编辑布局中。",
    ["Dispel Radar: Dispels"] = "驱散监控：可驱散类型",
    ["Smart: every kind you can remove, the right spell for each player. Or one kind only - Curses Only is a decurse radar."] = "智能模式：扫描所有你能够驱散的负面效果，并为每位队友选择对应驱散技能。也可只监控某一类型，例如仅诅咒。",
    ["Smart (not learned)"] = "智能模式（尚未学会对应技能）",
    ["Dispel Radar: In a Fight"] = "驱散监控：战斗中",
    ["In a fight a press cleanses whoever in your group lights up, then your friendly target. Only if the game stops showing that: Your Pick casts on your Party pick, else on you; Nothing waits."] = "战斗中按键会尝试驱散队伍框体中高亮提示的成员，然后是当前友方目标。如果客户端暂时无法提供该高亮提示，“当前选择”模式对队友选择目标施放（没有则对自己），“不施放”模式则等待，不进行替代驱散。",
    ["Your Pick"] = "当前选中队友",
    ["Party Frame Glow"] = "队伍框体高亮",
    ["The game's raid-style party frames light a member up who has a debuff, in a fight too. Game's Default, Only What I Can Dispel, or Off (the game's own setting; /reload after changing it)."] = "游戏的团队样式小队框体会高亮显示受到负面效果影响的成员，战斗中也适用。可选择游戏默认高亮、只高亮自己能驱散的效果，或完全关闭（改变后需 /reload）。",
    ["Game's Default"] = "游戏默认",
    ["Party Frame Glow Pulse"] = "队伍框体高亮脉冲",
    ["On: that glow pulses (the game's own pulse). Off: as the game had it."] = "开启：发光脉冲（游戏自身的脉冲）。关闭：如游戏所示。",
    ["Dispel Radar: Glow Its Button"] = "驱散监控：高亮对应按钮",
    ["On: the button with your Dispel Radar bind glows while someone near you has something you can remove."] = "开启：当您附近的人有可以移除的东西时，带有驱散雷达绑定的按钮会发光。",
    ["Put Dispel Radar on a Button"] = "将驱散雷达放在按钮上",
    ["Press the button you want Dispel Radar on. It's also in All Keybinds, Game Actions."] = "按您想要打开“驱散雷达”的按钮。它也位于所有按键绑定、游戏操作中。",
    ["Heals: 5 Buttons, D-pad, Wheel"] = "治疗选队友：5 个按键、十字方向键或轮盘",
    ["How the one you pick is marked"] = "您选择的选项是如何标记的",
    ["One bind buffs who needs it"] = "单键为需要增益的队友施法",
    ["One bind removes debuffs"] = "单键驱散队友负面效果",
    ["5 Buttons"] = "5 个按钮",
    ["A button for each member: bind Target Self and Party Member 1 - 4 in Quick Binds. Its bind turns it on and off."] = "为自己及四名队友分别绑定一个目标选择键。在“快速绑定”中设置，使用相应按键开启或关闭。",
    ["The D-pad (or A / B / X / Y) chooses a party member. Its bind turns it on and off."] = "使用十字方向键（或 A／B／X／Y）选择队友，绑定的按键可以开启或关闭该功能。",
    ["On a Button"] = "在按钮上",
    ["Press Again"] = "再次按键",
    ["Targeting"] = "目标选择",
    ["Combat Out of a Fight"] = "非战斗时使用战斗按键组",
    ["Modifier"] = "组合键",
    ["Party Wheel"] = "队友选择轮盘",
    ["You and your party in a ring, with health bars."] = "你和你的队伍围成一圈，有生命值。",
    ["On a Spell"] = "法术",
    ["Heal"] = "治疗",
    ["Wheel Look"] = "轮盘外观",
    ["Stay Open"] = "保持轮盘开启",
    ["Highlight"] = "高亮",
    ["How the one you picked is marked."] = "设置被选中队友的高亮标记样式。",
    ["Pulse"] = "脉冲",
    ["One bind buffs the next player who needs it."] = "单个快捷键为下一名需要此增益的队友施放技能。",
    ["A bind of its own for one more of your buffs."] = "为另外一种增益效果设置独立快捷键。",
    ["One bind removes the next debuff you can; frames light up for it."] = "使用单个快捷键驱散下一个可处理的队友负面效果，队伍框体会高亮提示。",
    ["Glow Pulse"] = "发光脉冲",
    ["On: the buttons below with a hold bind do it when held about half a second; a tap does their own bind, done as you let go (not as you press). Off: every button acts on the press, as always."] = "开启后，为下方按钮配置的长按操作会在按住约半秒后触发；短按原有操作在松开按键时执行。关闭后所有按键恢复按下即触发的方式。",
    ["Alone"] = "单独使用",
    ["Hold A"] = "按住 A",
    ["Nothing"] = "不执行操作",
    ["Hold B"] = "按住 B",
    ["Hold X"] = "按住 X",
    ["Hold Y"] = "按住 Y",
    ["LT"] = "LT",
    ["RT"] = "RT",
    ["Hold RT + A"] = "按住 RT＋A",
    ["LT + RT"] = "LT + RT",
    ["Hold LT + RT + A"] = "按住 LT＋RT＋A",
    ["Hold LT + RT + X"] = "按住 LT＋RT＋X",
    ["Hold a button about half a second, then let go, for a second bind on it. A quick tap does the button's own bind as you let go."] = "按住某个按钮约半秒再松开，即可执行其第二组长按绑定；快速短按则在松开时执行该按钮原有绑定。",
    ["A / B / X / Y on their own."] = "单独按下 A／B／X／Y。",
    ["Selling"] = "出售",
    ["Auto Repair"] = "自动修理",
    ["On: a repair merchant fixes your gear with your gold. Hold Shift on a keyboard to skip. Experimental."] = "开启后，与修理商人对话时自动用个人金币修理装备。按住键盘 Shift 可跳过（实验性）。",
    ["Auto Sell Junk"] = "自动出售灰色垃圾",
    ["On: gray junk is sold at a merchant. Hold Shift on a keyboard to skip. Experimental."] = "开启后，与 NPC 商人对话时自动出售灰色品质的垃圾物品。按住键盘 Shift 可跳过（实验性）。",
    ["Sell My Sell List"] = "出售清单中的物品",
    ["On: items you put on your sell list are sold at every merchant."] = "开启后，与 NPC 商人对话时自动出售你加入“出售清单”的物品。",
    ["My Sell List"] = "我的出售清单",
    ["A: your bag items - A on one puts it on the list (or takes it off)."] = "按 A 浏览背包物品；对某件物品按 A 可将其添加到出售清单，再按一次则移除。",
    ["Sell Gear I Can't Use"] = "出售当前职业无法使用的装备",
    ["On: green or lower armor and weapons your class can never use are sold (plate on a mage...)."] = "开启后，可出售当前职业无法使用的绿色及以下品质护甲和武器，例如法师无法穿戴的板甲。",
    ["Sell White Gear Below"] = "出售低于指定物品等级的白色装备",
    ["White armor and weapons under this item level are sold. Left / right: the level."] = "出售物品等级低于设定值的白色护甲与武器。左右方向键调整阈值。",
    ["Ask Before Selling"] = "出售前确认",
    ["On: at a merchant the menu lists what would sell; A sells it, or keep some first."] = "开启后，在 NPC 商人处列出将要出售的物品；按 A 确认出售，也可先选择保留某些物品。",
    ["Repairing and selling at a merchant."] = "商人处的修理与自动出售功能。",
    ["Sell Gray Junk"] = "出售灰色垃圾",
    ["Sell My List"] = "出售清单物品",
    ["Edit My List"] = "编辑出售清单",
    ["Gear I Can't Use"] = "本职业无法使用的装备",
    ["White Gear Below"] = "低于等级的白色装备",
    ["Ask First"] = "先确认",
    ["Controller Forever"] = "Controller Forever",
    ["Put spells, macros and game actions on every button."] = "为每个按键绑定技能、宏或游戏操作。",
    ["A second set of binds for a fight or a hostile target."] = "用于战斗或敌对目标的第二组绑定。",
    ["Your layout: Compact, Final Fantasy or Trigger Bar, and its settings. A goes in."] = "选择手柄布局：紧凑、FF 风格或扳机键动作条。按 A 进入设置。",
    ["Your profiles, the Defaults for new characters, export / import and resets."] = "管理个人配置、新角色默认设置、导出、导入和重置。",
    ["Spells on your buttons, the item pickers and the Tracking List: still being tested."] = "按键技能、物品选择器及追踪列表仍处于测试阶段。",
    ["The menu, chat, quests and the trackpad."] = "菜单、聊天、任务与触控板设置。",
    ["Hide Menu Items"] = "隐藏菜单项目",
    ["Pick tabs and cards to hide from the menu. Search (Select) still finds them."] = "选择要从菜单中隐藏的标签页和设置卡片。仍可通过 Select 搜索找到它们。",
    ["R3  Loadout"] = "R3：切换配置方案",
    ["Main  (in use)"] = "主方案（使用中）",
    ["Tank"] = "坦克",
    ["Healer"] = "治疗",
    ["R3 inside, or < > here: switch"] = "在设置内部按 R3，或使用此处的左右箭头切换。",
    ["Undo Last Bind"] = "撤消上次绑定",
    ["Next Set"] = "下一组",
    ["-  D-pad Up past the top button reaches Extra Buttons and combo options."] = "在最上方按钮继续按方向键上，可进入扩展按键和组合选项。",
    ["Pick tabs and cards to hide"] = "选择要隐藏的标签页和设置卡片",
    ["Final Fantasy Layout"] = "最终幻想式布局",
    ["No-Trigger Bar on the Bottom"] = "将未按扳机键的动作条放在底部",
    ["Final Fantasy: the no-trigger bar at the bottom, LT + RT above it."] = "FF 风格布局：未按扳机键的动作条位于底部，LT＋RT 组合层位于其上方。",
    ["Keep Bars the Same Size"] = "保持所有动作条相同大小",
    ["On: all four bars stay one size as you hold LT / RT; the one in use is brighter. Off: the one in use grows."] = "开启后，按住 LT／RT 时四条动作条保持相同大小，当前使用的动作条会更亮；关闭后，当前动作条会放大。",
    ["Trigger Icons (Final Fantasy)"] = "显示扳机键图标（FF 风格）",
    ["Shown: the LT / RT trigger icons in the Final Fantasy layout too."] = "在 FF 风格布局中也显示 LT／RT 扳机键图标。",
    ["Hidden"] = "隐藏",
    ["Bars"] = "动作条",
    ["No Trigger"] = "未按扳机键",
    ["Move Left / Right"] = "左/右移动",
    ["Move Up / Down"] = "上/下移动",
    ["Reset Bar Position"] = "重置动作条位置",
    ["Same for All Bars"] = "所有动作条使用相同设置",
    ["On: the three see-through rows below set all four bars. Off: only the one picked."] = "开启后，下方三个透明度选项对全部四条动作条生效；关闭后只影响当前选中的动作条。",
    ["Faded When Not in Use"] = "闲置时淡出",
    ["Faded in Combat"] = "战斗时淡出",
    ["When in Use"] = "使用时",
    ["Back Buttons Sit"] = "背键排列位置",
    ["Outside: past the D-pad and A / B / X / Y. Inside: between them. L4 / R4 and L5 / R5 together."] = "外侧：在方向键和 A／B／X／Y 之外；内侧：位于两组按键之间。L4／R4 与 L5／R5 成组排列。",
    ["Outside"] = "外侧",
    ["L4 / R4 Back Buttons"] = "L4 / R4 背键",
    ["Back paddles (Elite, DualSense Edge, Steam Deck)."] = "背部拨片（适用于 Elite、DualSense Edge、Steam Deck）。",
    ["Set Up L4"] = "设置 L4",
    ["Set Up R4"] = "设置 R4",
    ["Edit Layout: Move All L4 / R4"] = "编辑布局：移动所有 L4 / R4",
    ["Edit Layout: L4"] = "编辑布局：L4",
    ["Edit Layout: R4"] = "编辑布局：R4",
