    ["The second pair of back paddles."] = "第二对手柄背键。",
    ["Set Up L5"] = "设置 L5",
    ["Set Up R5"] = "设置 R5",
    ["Edit Layout: Move All L5 / R5"] = "编辑布局：移动所有 L5 / R5",
