    ["Edit Layout: R5"] = "编辑布局：R5",
    ["Extra Buttons Sit"] = "扩展按键排列位置",
    ["Outside: past the D-pad and A / B / X / Y. Inside: between them."] = "外侧：位于十字方向键及 A／B／X／Y 外侧；内侧：位于两组按键之间。",
    ["Extra Buttons (E1 - E4)"] = "额外按钮 (E1 - E4)",
    ["Four more buttons (Flydigi C, Z, LM, RM). Set each up below first."] = "额外四个按键（飞智 C、Z、LM、RM）。请先在下方逐个设置。",
    ["Set Up E1"] = "设置E1",
    ["Set Up E2"] = "设置 E2",
    ["Set Up E3"] = "设置 E3",
    ["Set Up E4"] = "设置 E4",
    ["Show and Name"] = "显示和命名",
    ["Shown: this button is drawn with your other buttons. Hidden: it isn't drawn, and still works. The rest of its group stays as it is."] = "显示：与其他动作按钮一起显示此按钮。隐藏：按钮不显示，但功能仍然有效；同组其他按钮不受影响。",
    ["What this button is called on your buttons, in All Keybinds and in CF's words: left / right picks a ready name (C, Z, P1 - P4, M1 - M4...), A types your own (up to 8 letters). Its own name again brings back its own picture."] = "设置这个按键在动作按钮、“全部按键绑定”及 CF 提示中的名称。左右方向键可选预设名称（如 C、Z、P1–P4、M1–M4）；按 A 可输入最多 8 个字符的自定义名称。恢复原名会重新使用原版按键图标。",
