    ["Edit Layout: Move All E1 - E4"] = "编辑布局：移动所有 E1 - E4",
    ["Edit Layout: E1"] = "编辑布局：E1",
    ["Edit Layout: E2"] = "编辑布局：E2",
    ["Edit Layout: E3"] = "编辑布局：E3",
    ["Edit Layout: E4"] = "编辑布局：E4",
    ["Scuf G1 - G5"] = "SCUF G1–G5",
    ["Scuf 5 Buttons"] = "SCUF 五个扩展键",
    ["G1 - G5 (SCUF Envision). One bind each, on every modifier."] = "SCUF Envision 的 G1–G5：每个组合键层均可独立绑定。",
    ["Set Up Scuf Buttons"] = "设置 Scuf 按钮",
    ["Set G1 - G5 to keys in iCUE first. A, then press G1 to G5."] = "先在 iCUE 中将 G1–G5 映射为键盘按键。按 A 开始检测，再依次按下 G1 至 G5。",
    ["Not set"] = "未设置",
    ["Edit Layout: All G1 - G5"] = "编辑布局：所有 G1 - G5",
    ["Edit Layout: G1"] = "编辑布局：G1",
    ["Edit Layout: G2"] = "编辑布局：G2",
