    ["Edit Layout: G4"] = "编辑布局：G4",
    ["Edit Layout: G5"] = "编辑布局：G5",
    ["All Back Buttons"] = "所有背键",
    ["Check My Back Buttons"] = "检测背键输入",
    ["Press one: see if the game gets it, and how to fix it for your controller."] = "按下任一背键，查看游戏能否识别，并获得适用于当前手柄的排查说明。",
    ["Reset Back Buttons"] = "重置背键",
    ["Back buttons to their defaults. Any button they took over is given back."] = "将背键恢复为默认设置，并还原被背键占用的原有按键。",
    ["The two back paddles (Elite, DualSense Edge, Steam Deck)."] = "两枚背键（适用于 Elite、DualSense Edge、Steam Deck）。",
    ["Four more buttons (Flydigi C, Z, LM, RM)."] = "另外四个按钮（飞智C、Z、LM、RM）。",
    ["The SCUF Envision's G1 - G5 row."] = "SCUF Envision 手柄的 G1–G5 按键组。",
    ["Set Up G1 - G5"] = "设置 G1 - G5",
    ["Check what the game gets, or put them all back."] = "检查游戏实际接收到的输入，或恢复全部背键默认设置。",
    ["Check Them"] = "检测这些按键",
    ["Reset All"] = "全部重置",
    ["My Profiles"] = "我的配置文件",
    ["Save a Profile"] = "保存配置文件",
    ["Nothing saved"] = "尚未保存配置文件",
    ["Older settings-only profile. Load it, then Upgrade Older Profile to enable automatic saving. A: load (reloads). X: rename. Y: delete."] = "此配置文件只包含旧版设置。请先加载，再通过“升级旧版配置文件”转换为支持自动保存的新格式。操作键：A 加载（并重新加载界面）、X 重命名、Y 删除。",
    ["Delete"] = "删除",
    ["Upgrade Older Profile"] = "升级旧版配置文件",
    ["Turn an older settings-only profile into one that saves itself, from your look, layout and settings now."] = "将只包含设置的旧版配置文件升级为可自动保存的配置，采用当前的外观、布局和设置。",
    ["None loaded"] = "未加载配置",
    ["Undo Profile Load"] = "撤销加载配置文件",
    ["Put back the look, layout and settings you had before the last profile load. Binds aren't touched. Reloads."] = "恢复上次加载配置文件之前的外观、布局和设置。按键绑定不变；需要重新加载界面。",
    ["Default Settings"] = "默认设置",
    ["Save Default Settings"] = "保存默认设置",
    ["Save the single settings default new characters start with. Saving again replaces it."] = "保存新角色初始使用的默认设置，再次保存会替换旧默认设置。",
    ["Load My Default Settings"] = "加载我的默认设置",
    ["Puts your Default Settings on this character now. Binds stay. Reloads; Undo Reset Settings puts yours back."] = "将保存的默认设置应用到当前角色，保持按键绑定不变，并重新加载界面。可通过“撤销设置重置”恢复。",
    ["Use My Default"] = "使用我的默认配置",
    ["On: new characters start with your saved default. Off: CF's own settings."] = "开启后新角色使用你保存的默认设置；关闭则使用 Controller Forever 原始默认值。",
    ["Default Keybinds"] = "默认按键绑定",
    ["Set Up Your Binds"] = "设置快捷键",
    ["Jump, Interact, the wheels, the map and more, one by one beside All Keybinds: bind each, pick another button or skip."] = "依次配置跳跃、交互、快捷轮盘、地图等常用操作。可绑定当前按键、选择其他按键或跳过。",
    ["Lock My Binds"] = "锁定按键绑定",
    ["On: no profile, Default, code, tutorial or rank update can change your binds. They still work as bound."] = "开启后，配置文件、默认设置、导入代码、教程及技能等级更新均不能改动当前绑定；现有快捷键仍正常工作。",
    ["Save My Keybinds"] = "保存我的按键绑定",
    ["Save this character's binds only, by name: every button, loadout and bar slot. Other characters never see it."] = "将当前角色所有按键、配置方案和动作条栏位保存为命名方案；其他角色不会看到此方案。",
    ["This character's binds only. A: load (reloads; not while Lock My Binds is on). X: rename. Y: delete."] = "只显示当前角色保存的按键方案。A：加载并重新载入界面（锁定按键时无法加载）；X：重命名；Y：删除。",
    ["Undo Keybind Load"] = "撤销上次按键方案加载",
    ["Put back the binds this character had before its last My Keybinds load. Reloads."] = "恢复上次加载“我的按键绑定”之前的配置，并重新加载界面。",
    ["Save as Default Keybinds"] = "保存为默认按键绑定",
    ["This loadout's binds, without class abilities, saved only for new characters."] = "将当前配置方案中不涉及职业技能的快捷键保存为新角色默认绑定。",
    ["Load My Default Keybinds"] = "加载默认按键绑定",
    ["Puts your Default Keybinds on this loadout now. Your class abilities stay where it has nothing. Undo Keybind Load puts yours back."] = "将默认按键绑定应用到当前配置方案。没有对应默认绑定的位置会保留已有的职业技能；可以通过“撤销加载按键方案”恢复。",
    ["Use Default Keybinds"] = "使用默认按键绑定",
    ["On: new characters start with your Default Keybinds. Off: Controller Forever's own binds."] = "开启后新角色使用自定义默认按键；关闭则使用 Controller Forever 默认绑定。",
    ["Export / Import"] = "导出/导入",
    ["Export: Everything"] = "导出全部配置",
    ["Export: Settings"] = "导出设置",
    ["Export: Binds"] = "导出按键绑定",
    ["Import a Code"] = "导入配置代码",
    ["Paste a code (Ctrl+V) and load it. Undo below puts yours back."] = "粘贴配置代码（Ctrl＋V）并加载。可以通过下方撤销功能恢复原设置。",
    ["Undo Last Import"] = "撤销上次导入",
    ["Puts back what you had before the last import. Reloads."] = "恢复上次导入前的设置，并重新加载界面。",
    ["Nothing to undo"] = "没有可撤销的操作",
    ["Browse Party/Raid Setups"] = "浏览小队／团队配置",
    ["Discover setups shared by group members and request them without targeting anyone. Experimental."] = "发现队友共享的配置，并在无需选中队友的情况下请求导入。实验性功能。",
    ["Resets"] = "重置",
    ["Reset All Keybinds"] = "重置全部按键绑定",
    ["Every button with a default goes back to it. Your other binds stay. This set only."] = "仅对当前配置方案生效：将有默认值的按钮恢复默认绑定，其他手动绑定保留。",
    ["Reset All Settings"] = "重置全部设置",
    ["Every setting back to Controller Forever's own settings. Binds stay. Reloads. Undo below."] = "将全部设置恢复为 Controller Forever 原始默认值；按键绑定保持不变，界面会重新加载。可通过下方选项撤销。",
    ["Undo Reset Settings"] = "撤销设置重置",
    ["Puts back the settings from before the last reset. Reloads."] = "恢复上次重置前的设置，并重新加载界面。",
    ["Reset Everything (All Characters)"] = "清除所有角色的全部 CF 设置",
    ["Clears everything CF has saved, every character. Reloads. Undo below."] = "清除 Controller Forever 为所有角色保存的全部配置，然后重新加载界面。可通过下方的撤销选项恢复。",
    ["Undo Reset Everything"] = "撤销清除全部设置",
    ["Puts back everything from before the last Reset Everything. Reloads."] = "恢复上次“清除全部设置”前的所有内容，并重新加载界面。",
    ["Settings saved only for new characters."] = "这些默认设置只会应用于新角色。",
    ["Set up and lock your binds, save this character's binds only (My Keybinds), or save the binds new characters start with."] = "设置与锁定按键，保存当前角色专属绑定（我的按键），或保存新角色初始使用的默认绑定。",
    ["Save"] = "保存",
    ["Binds: Unlocked"] = "按键绑定：未锁定",
    ["Save Default"] = "保存默认配置",
    ["Load Default"] = "加载默认配置",
    ["Default: On"] = "默认设置：开启",
    ["Your setup as a code for a friend (export), or load one (import)."] = "可以将配置导出为分享代码，或导入其他人的配置代码。",
    ["Import"] = "导入",
    ["Undo"] = "撤消",
    ["Party Setups (Experimental)"] = "队伍治疗配置（实验性）",
    ["Binds or settings back to the start, and their undos."] = "重置按键绑定或设置，并管理对应的撤销选项。",
    ["Reset Keybinds"] = "重置按键绑定",
    ["Reset Settings"] = "重置设置",
    ["Reset Everything"] = "清除所有设置",
    ["Trigger Bar"] = "扳机键动作条",
    ["Dim Others"] = "淡化其他动作条",
    ["How solid the sections you aren't using are. 100% doesn't dim them, 0% hides them."] = "调整未使用动作条区域的不透明度：100% 不淡出，0% 完全隐藏。",
    ["Size"] = "大小",
    ["How big the Trigger Bar is, on top of your whole layout's size."] = "在整体布局大小基础上，单独调整扳机键动作条尺寸。",
    ["Reset Trigger Bar"] = "重置扳机键动作条",
    ["The Trigger Bar back where it starts, at its starting size, Dim Others too."] = "将扳机键动作条恢复初始位置和大小，同时重置“淡化其他动作条”设置。",
    ["Edit Layout: Select"] = "编辑布局：Select",
    ["Bind Select On (to start): Select alone is the game's Select, LT + Select this menu. Off: Select opens this menu."] = "默认启用 Select 独立绑定：单按 Select 执行游戏原生功能，LT＋Select 打开此菜单。关闭后，单按 Select 即打开此菜单。",
    ["Menu"] = "菜单",
    ["Menu Size"] = "菜单大小",
    ["This menu bigger or smaller (60% - 150%). It never gets bigger than your screen."] = "调整当前菜单大小（60%–150%），不会超出屏幕范围。",
    ["Start Menu Centered"] = "Start 菜单居中",
    ["Centres the game's Start menu."] = "使游戏原生 Start 菜单居中显示。",
    ["Hide Error Spam"] = "隐藏重复错误提示",
    ["On: hides the red Not ready / Out of range / No target lines."] = "开启后，不再显示红色“未就绪／超出距离／没有目标”提示。",
    ["Form Color Rings"] = "形态色环",
    ["On: every button gets a ring in your form or stance colour."] = "为每个技能按钮添加按当前变形形态或战斗姿态颜色显示的圆环。",
    ["Cannibalize on Interact"] = "交互键使用食尸技能",
    ["On: on a Humanoid or Undead corpse with nothing left for you to loot, Interact casts Cannibalize on it, and shows its icon, while you're within its reach. Out of a fight only."] = "开启后，当你面对已无战利品可拾取的人形或亡灵尸体时，交互键会在有效距离内尝试使用亡灵种族技能“食尸”，并显示相应图标。仅脱战可用。",
    ["Stop Attacking on Interact"] = "交互时停止自动攻击",
    ["On: Interact on an enemy you're already hitting stops your auto attack (the game's own way). Off: in a fight it keeps you attacking; holding Interact then no longer loots everything at once."] = "开启后，对正在攻击的敌人按交互键会停止自动攻击（游戏原生行为）。关闭后，战斗中不会停止自动攻击，但长按交互键也不能再一次性拾取全部物品。",
    ["Auto Loot"] = "自动拾取",
    ["On: looting puts everything in your bags at once (the game's own Auto Loot). Off: you pick from the loot window."] = "开启后直接拾取怪物掉落的全部物品（游戏原生自动拾取）；关闭后从拾取窗口手动选择。",
    ["Hide Loot Window"] = "自动拾取时隐藏物品窗口",
    ["With Auto Loot on: the loot window doesn't pop up while it empties. If something is left (full bags, an item that asks first) it shows."] = "打开自动战利品：战利品窗口在清空时不会弹出。如果留下了什么东西（满包，首先询问的物品），它就会显示。",
    ["Chat"] = "聊天",
    ["Whisper Alert"] = "密语提醒",
    ["On Screen: who and what, a moment. Reply Box: the reply keyboard opens (out of a fight). Bind: Reply to Whisper."] = "屏幕提示：短暂显示密语发送人和内容；回复框：脱战时打开密语回复输入框。可绑定“回复密语”操作。",
    ["On Screen"] = "显示在屏幕上",
    ["Voice Chat Channel"] = "语音聊天频道",
    ["Where the voice chat app's lines go (/cfchat). Back to Auto at every login. Bind: Voice Chat Channel toggles it in game."] = "设置语音聊天工具的消息发送频道（/cfchat）；每次登录恢复自动模式。也可为“语音聊天频道”绑定切换键。",
    ["Auto (your group)"] = "自动（当前队伍）",
    ["Report Reminder"] = "错误报告提醒",
    ["On: after a reload, one line in chat says when Controller Forever recorded problems, and where the file to send is."] = "开启后，如果插件记录到问题，重新加载界面时会在聊天栏提示记录时间以及报告文件的位置。",
    ["Quests"] = "任务",
    ["Auto Accept Quests"] = "自动接取任务",
    ["Takes quests for you. Not with the game's controller UI on: there your A takes them."] = "自动接受任务。但启用游戏原生手柄界面时，此功能不起作用，需通过 A 键接受任务。",
    ["Auto Turn In Quests"] = "自动交付任务",
    ["With the controller UI: the first page is turned for you, the reward is your A (closing it from an addon breaks LT / RT)."] = "启用游戏原生手柄界面时，插件可自动翻到任务交付页，但任务奖励仍需你按 A 选择；其他插件强制关闭窗口可能干扰 LT／RT。",
    ["Trackpad"] = "触控板",
    ["Mouse / Trackpad Takeover"] = "鼠标／触控板接管",
    ["What touching the mouse or trackpad does while on the controller."] = "调整手柄模式下触摸鼠标或触控板时的操作方式。",
    ["not available in this client"] = "在此客户端中不可用",
    ["Trackpad Pointer Hand-Off"] = "触控板指针接管",
    ["On: a click or tap frees the pointer until you touch the controller."] = "点击鼠标或轻触触控板后，系统指针由鼠标控制，直到再次使用手柄。",
    ["Trackpad Picks in Wheels"] = "触控板选择轮盘选项",
    ["Steam Deck: the trackpad pointer picks in wheels."] = "在 Steam Deck 上可以通过触控板指针选择轮盘选项。",
    ["Stick Pointer Speed"] = "摇杆指针移动速度",
    ["How fast the right stick moves the Mouse Pointer bind."] = "调整右摇杆控制鼠标指针时的移动速度。",
    ["How the menu and the game's messages act."] = "调整菜单和游戏提示的行为。",
    ["Whispers and the voice chat app's lines."] = "密语以及语音聊天工具的消息。",
    ["Center Start Menu"] = "Start 菜单居中",
    ["Hide Errors"] = "隐藏错误提示",
    ["Form Rings"] = "形态技能颜色圆环",
    ["Interact Stops Attack"] = "交互时停止攻击",
    ["Whispers"] = "密语",
    ["Voice Chat"] = "语音聊天",
    ["Talking to quest givers."] = "与任务发布 NPC 的互动。",
    ["Auto Accept"] = "自动接任务",
    ["Auto Turn In"] = "自动交任务",
    ["The trackpad, the mouse and the stick pointer."] = "触控板、鼠标和摇杆指针。",
    ["Pointer Hand-Off"] = "指针控制权切换",
    ["Picks in Wheels"] = "选择轮盘选项",
    ["Stick Speed"] = "摇杆指针速度",
    ["Edit Layout: Both LB and RB"] = "编辑布局：LB 和 RB",
    ["Edit Layout: LB"] = "编辑布局：LB",
    ["Edit Layout: RB"] = "编辑布局：RB",
    ["Hold Binds"] = "长按绑定",
    ["LT + LB Hold Binds"] = "LT＋LB 长按绑定",
    ["RT + RB Hold Binds"] = "RT＋RB 长按绑定",
    ["Holding LB / RB: Hold Binds Only"] = "按住 LB／RB 时仅使用长按绑定",
    ["On (to start): only a quick tap does LB's / RB's own bind. Held (in a fight too), only your hold binds work."] = "开启后，快速短按执行 LB／RB 原有操作；持续按住只执行设置的长按操作，战斗中也有效。",
    ["Modifiers"] = "组合键",
    ["LB as a Modifier"] = "L1 作为组合键",
    ["RB as a Modifier"] = "R1 作为组合键",
    ["LB / RB as your own buttons. Hold both and push the right stick to zoom."] = "将 LB／RB 设为可独立绑定的按钮；同时按住两键并推动右摇杆可缩放镜头。",
    ["LB / RB holds (on while LB / RB are modifiers): bind them in All Keybinds."] = "当 LB／RB 被设为组合键时，可在“全部按键绑定”中设置它们的长按操作。",
    ["Edit Layout: Both"] = "编辑布局：两个按钮",
    ["Hold Binds Only"] = "仅执行长按绑定",
    ["Off: that button is a plain button, its hold binds wait."] = "关闭时，此键作为普通按键使用，长按操作暂不生效。",
    ["CF Look (Every Skin)"] = "CF 整体皮肤外观",
    ["Ready-Made Look"] = "预设外观",
    ["Make It My Own: every skin on, every line yours to change. Left / right: the next look."] = "启用全部皮肤模块，并允许独立调整每一项设置；左右方向键切换预设外观。",
    ["Make It My Own"] = "自定义外观",
    ["Accent Color"] = "强调色",
    ["One colour for the borders and frame art of every skin."] = "使用统一颜色作为各类皮肤的边框和框体装饰颜色。",
    ["Border"] = "边框",
    ["The border round the minimap, chat and meter."] = "设置小地图、聊天框与统计面板的边框。",
    ["Backgrounds"] = "背景",
    ["Dark: solid black behind the chat and meter."] = "深色样式：聊天窗口和统计面板后显示纯黑背景。",
    ["Bar Texture"] = "进度条材质",
    ["The bars of the meter and your frames."] = "设置统计面板和单位框体的进度条材质。",
    ["Tooltips"] = "工具提示",
    ["Dark: the game's tooltips in a flat dark panel with a thin edge."] = "深色样式：物品提示窗口使用暗色平面背景与细边框。",
    ["Font"] = "字体",
    ["The chat, meter and frames' text font. Your Own Font: a .ttf font of yours - make the folder Interface\\AddOns\\ControllerForever_Fonts, put the font in it named Custom.ttf, then restart the game (a /reload doesn't find a new file). Without it you get the game's font. CF doesn't come with that font: only you have it."] = "调整聊天、伤害统计和单位框体文字字体。若选择“自定义字体”，请创建 Interface\\AddOns\\ControllerForever_Fonts 文件夹，放入名为 Custom.ttf 的字体文件，再完全重启游戏（/reload 无法加载新增字体）。如果没有文件，会退回游戏原生字体。CF 不附带该字体文件。",
    ["Text Outline"] = "文字描边",
    ["A dark edge round the text."] = "在文字外侧添加深色描边。",
    ["All Game Text Font"] = "所有游戏文字字体",
    ["Every bit of game text in this font. Experimental. Your Own Font: as CF Look > Font says."] = "将此字体用于游戏中的所有文本（实验性）。自定义字体的安装方法见“CF 外观 → 字体”。",
    ["All Game Text Size"] = "所有游戏文字大小",
    ["Every bit of game text smaller or bigger. Experimental."] = "整体放大或缩小游戏文字（实验性）。",
    ["CF Window Look"] = "CF 窗口外观",
    ["The look of CF's own windows: this menu and its popups, All Keybinds, the tutorial, the loot roll window, Controller Bags, the Controller AH and the Damage Meter panel. CF Ornate: the gold frame, as always. Clean Dark: flat and dark with a thin grey line, in silver. Game's: the game's own window frame, stone and plain rows and tabs, in the game's yellow. Classic: the same with the old silver frame. Your skins and the game's windows stay as they are. Left / right: the next look."] = "选择 CF 自带窗口（当前设置菜单、弹窗、按键绑定、教程、战利品掷骰、整合背包、手柄拍卖行及伤害统计面板）的外观。“华丽”：经典金色边框；“简洁深色”：暗色底、银灰细线；“游戏原生”：使用游戏原生窗框、石质材质及黄色标签；“经典”：早期银色边框。你的皮肤和游戏窗口样式不受影响。",
    ["CF Ornate"] = "CF 华丽样式",
    ["CF Window Background"] = "CF 窗口背景",
    ["How much of the world shows through CF's own windows: 100% is solid, 50% the most see-through. Only the backs fade: the words, items and lines stay solid, and the tutorial stays solid. The Damage Meter panel has its own Opacity. Left / right."] = "调整 CF 窗口背景的不透明度：100% 完全不透明，50% 最透明。只有背景淡出，文字、物品图标和边框保持清晰；教程窗口始终保持不透明。伤害统计面板有单独的不透明度设置。",
    ["CF Window Border"] = "CF 窗口边框",
    ["The edge round CF's own windows and their cards, whatever the look: Ornate (CF's gold frame), Game's (the game's window frame), Classic (the old silver one), Crisp Line (a sharp line with a soft shadow), Thin (a thin line) or None. It starts as your CF Window Look's own; another one makes the look Make It My Own. Left / right: the next border."] = "选择 CF 窗口及卡片的边框：华丽金边、游戏原生窗框、经典银边、锐利描边（带柔和阴影）、细线或无边框。默认跟随 CF 窗口外观，单独修改后会切换到自定义样式。左右方向键切换边框。",
    ["Ornate"] = "华丽",
    ["CF Window Color"] = "CF 窗口主色",
    ["The colour of CF's own windows' gold: their lines and trim, the lit row, tab and card, and the headings. CF Gold (as always), Game's Yellow, Silver, White, Class (your class's colour), CF Look's Accent (when CF Look has an accent colour), Blue, Green, Red, Purple or Orange. It starts as your CF Window Look's own; another one makes the look Make It My Own. Left / right: the next colour."] = "设置 CF 窗口边框、装饰线、选中项、标签和标题的主色。可选 CF 金色、游戏黄、银色、白色、职业颜色、CF 主题强调色、蓝、绿、红、紫或橙色。默认跟随窗口外观，单独修改后切换为自定义。左右方向键选择颜色。",
    ["CF Gold"] = "CF 金色",
    ["CF Windows: Gold as Text"] = "CF 窗口：金币显示为文字",
    ["Prices as 3g 30s 40c instead of coin pictures, in Controller Forever's own windows."] = "在 CF 窗口中将金币价格显示为 3g 30s 40c 形式的文字，而不是金银铜图标。",
    ["CF Windows: Game's Tooltip Too"] = "CF 窗口：同时显示游戏原生提示框",
    ["The game's own item tooltip beside Controller Forever's windows too (it covers part of the screen)."] = "在 CF 窗口旁同时显示游戏原生物品提示框，可能会遮挡部分画面。",
    ["CF Windows: Window Size"] = "CF 窗口大小",
    ["How big Controller Forever's own windows are, 80 to 110 %."] = "调整 Controller Forever 自带窗口大小（80%–110%）。",
    ["Frames"] = "单位框体",
    ["Move Your Frame in Edit Layout"] = "在编辑布局中移动玩家框体",
    ["Mirror Target Frame With Your Frame"] = "将目标框体与玩家框体镜像排列",
    ["On: your target's frame sits opposite yours, the same height, as in a mirror. Move yours and it follows."] = "开启后，目标框体会在玩家框体对侧以相同高度显示。移动玩家框体时，目标框体会随之调整。",
    ["Move the Target Frame in Edit Layout"] = "在编辑布局中移动目标框体",
    ["Frame Style"] = "框体风格",
    ["Kingdom Hearts: every frame - yours, your target's, focus, pet, boss, target-of-target, party and raid frames (the party frames raid-style or classic, and the pets on them) - as a round portrait with curved health and power; yours with a combo point number, the others with their name, most with their level; a debuff you can remove shows as one icon on each party and raid frame, instead of the game's glow. Fancy Frames: every frame the same way, in a new look - the portrait in a steel ring with ice round it, a health blade with the health number at its tip, a wavy power blade with its number, a level badge and a gem that glows in a fight (your target's, focus and boss frames the mirror of yours; each raid-style party frame a small copy of yours - the ring with their face, the blades and their name, above the game's buff and debuff icons; the raid frames blades with a piece of the ring's ice at the end); every player's health in their class colour, yours too (the blade's steel turns red when low); one dispel icon on each frame, yours too, never a glow. Classic: the old frame art on every frame - yours, your target's, focus, pet, boss and target-of-target; each party frame (raid-style or classic) is a small copy of your frame - its portrait in the ring, level, name plate, health and power (the raid-style ones facing the other way, as your target frame) - and their pets a small classic pet frame; the raid frames get classic bars; a debuff you can remove shows as one icon on each party and raid frame, instead of the game's glow. The game's debuff icons and ready check stay on top. Classic reloads."] = "王国之心风格：将玩家、当前目标、焦点、宠物、首领、目标的目标、小队及团队框体统一改为圆形头像，配以弧形生命值和法力／能量条。玩家框体显示连击点数，其他单位显示名称，多数还显示等级。可由你驱散的负面效果会在队伍和团队框体上显示为单独图标，而非游戏原有的发光效果。\n\n华丽框体风格：同样统一全部单位框体，但采用另一套外观——头像镶在带冰晶装饰的金属圆环中；生命值以刀刃形状显示，末端显示数值；法力／能量条采用波浪刀刃，旁边显示数值；另有等级徽章及战斗时发光的宝石。目标、焦点、首领框体与玩家框体镜像排列；使用团队风格的小队框体显示为玩家框体的缩小版，头像和刀刃位于游戏原有增益、减益图标之上；团队框体的刀刃末端饰有冰晶。所有玩家生命条使用其职业颜色，包含你自己；生命过低时金属刀刃会变红。可驱散效果只显示图标，不显示发光提示。\n\n经典风格：玩家、当前目标、焦点、宠物、首领和目标的目标全部使用经典框体美术。小队框体无论采用团队样式还是经典样式，均显示为玩家框体的缩小版，包含圆环头像、等级、姓名、生命值和能量；团队样式的小队框体与目标框体一样朝向另一侧；队员宠物显示为小型经典宠物框体。团队框体采用经典生命／能量条。可驱散的负面效果显示为单独图标，代替原版发光提示。\n\n在上述风格中，游戏自带的负面效果图标和准备确认仍显示在最上层。切换经典风格需要重新加载界面。",
    ["Kingdom Hearts Portrait"] = "王国之心风格头像",
    ["With Frame Style: Kingdom Hearts, your portrait on the right (the bars run left) or on the left (they run right). Your raid-style party frames, their pets and the raid frames go with yours. Your target's, focus's, boss and target-of-target frames are on the other side. Your pet's is always on the left, where the game lets you click the pet frame, and the classic party frames' and their pets' too, over the game's portraits. Frame Style: Fancy Frames follows it the same way."] = "使用“王国之心”单位框体风格时，可将自己的头像放在右侧（生命／能量条向左延伸）或左侧（向右延伸）。团队风格的小队框体、队员宠物及团队框体随玩家方向排列；当前目标、焦点、首领及目标的目标会位于另一侧。玩家宠物框体始终放在左侧，以保留游戏的宠物交互能力；经典小队框体及宠物也沿用此方向。华丽框体使用相同规则。",
    ["Right"] = "右侧",
    ["Window Style"] = "窗口风格",
    ["Classic: the old silver border on vendor, mail, quest and other small windows. Reloads."] = "经典：NPC 商人、邮件、任务和其他小窗口上的旧银色边框。重新加载。",
    ["Frames Skin"] = "单位框体皮肤",
    ["On: CF's look for every unit frame - yours and your pet's, your target's and focus's, their targets' and the boss frames (the rows below). The party frames have their own: Party Frames."] = "开启后，对玩家、玩家宠物、当前目标、焦点、目标的目标、首领等单位框体应用 CF 外观。小队框体另在“队伍框体”中设置。",
    ["Skin Which Frames"] = "选择应用皮肤的框体",
    ["Which frames get the look: all of them, yours and your pet's, or your target's, focus's, their targets' and the boss frames. Rows that only change the frames it leaves out are hidden."] = "选择应用 CF 外观的单位框体：全部、仅玩家及宠物，或目标／焦点／对应目标及首领。与未启用框体有关的设置会自动隐藏。",
    ["All"] = "全部",
    ["Frame Art"] = "框体装饰",
    ["The art round the portrait and bars, an elite's gold dragon and the level's circle too."] = "设置头像与生命／资源条周围的装饰，也包括精英金龙标记和等级圆环。",
    ["Frame Color"] = "框体颜色",
    ["The frame art's colour."] = "设置框体装饰颜色。",
    ["Portrait"] = "头像",
    ["A face, a class icon, or no portrait."] = "选择显示角色头像、职业图标或隐藏头像。",
    ["Bar Panel"] = "动作条面板",
    ["Dark: a flat dark panel with a thin edge behind your bars. Best with Frame Art: Hidden."] = "深色样式：动作条后使用带细边框的暗色背景。建议同时隐藏装饰框体。",
    ["How see-through the frames are."] = "调整单位框体的不透明度。",
    ["Opacity in Combat"] = "战斗时不透明度",
    ["The same, in a fight."] = "设置战斗中的透明度。",
    ["Health Bar Texture"] = "生命条材质",
    ["The health bar's fill."] = "设置生命条的填充材质。",
    ["Health Bar Color"] = "生命条颜色",
    ["Class / Reaction colours, or Green to Red by health."] = "选择按职业／敌友关系显示颜色，或随剩余生命值从绿色逐渐变为红色。",
    ["Low Health Color"] = "低血量颜色",
    ["The health bar changes colour under this much health."] = "生命值低于设定阈值时，生命条改变颜色。",
    ["Low Health Color Is"] = "低血量提示颜色",
    ["The low health colour."] = "设置低血量提示使用的颜色。",
    ["Power Bar Texture"] = "资源条材质",
    ["The mana / rage / energy bar's fill."] = "设置法力／怒气／能量条的填充材质。",
    ["Power Color"] = "资源条颜色",
    ["Muted: mana, rage and energy in softer colours, so health stands out."] = "“柔和”模式降低法力、怒气和能量条的颜色饱和度，让生命值更醒目。团队风格框体需在游戏设置中启用资源条；王国之心、华丽和经典框体始终显示资源。",
    ["Health / Power Gap"] = "生命条与资源条间距",
    ["Pixels between your frame's health and power bars, so their numbers read apart. Left / right."] = "设置玩家框体生命条与资源条之间的像素间距，便于区分两个数值；左右方向键调整。",
    ["Bar Numbers"] = "动作条编号",
    ["The numbers on the bars."] = "显示进度条上的数值。",
    ["Mana: Five-Second Rule"] = "法力回复：五秒规则",
    ["A spark on your mana bar for the 5 seconds after a spell. Experimental."] = "施放技能后的五秒内，在法力条上显示提示光效（实验性）。",
    ["Druid Mana in Forms"] = "德鲁伊变形时显示法力",
    ["Druids: a thin mana bar in Bear and Cat Form. Experimental."] = "德鲁伊处于熊形态或猎豹形态时，显示细法力条（实验性）。",
    ["Threat on Target"] = "目标仇恨值",
    ["Your threat on the target, as a % over its frame. Experimental."] = "在目标框体上方以百分比显示你对目标的仇恨值（实验性）。",
    ["The name, level and numbers' font. Your Own Font: as CF Look > Font says."] = "设置姓名、等级和数值字体。自定义字体说明见“CF 外观 → 字体”。",
    ["Text Size"] = "文字大小",
    ["The name, level and numbers' size."] = "调整姓名、等级和数值文字大小。",
    ["A dark edge round the letters."] = "字母周围有深色边缘。",
    ["Name"] = "姓名",
    ["The name over the frame."] = "设置框体上方的名称文字。",
    ["Name Color"] = "名称颜色",
    ["The name's colour."] = "设置名称文字颜色。",
    ["Level"] = "等级",
    ["The level number and its circle."] = "设置等级数字及其外围圆环。",
    ["Name Background (Target)"] = "名称背景（目标）",
    ["The coloured strip behind the target's name."] = "目标名字后面的彩色条。",
    ["Combat / Rest Glow"] = "战斗／休息状态高亮",
    ["The red fight glow and the yellow rest glow."] = "战斗时显示红色光效，休息时显示黄色光效。",
    ["Portrait Hit Numbers"] = "头像上方的伤害／治疗数字",
    ["Damage and healing numbers over your portrait."] = "在玩家头像上显示受到的伤害及获得的治疗数值。",
    ["Resting Zzz"] = "休息状态 Zzz 标记",
    ["The Zzz by your portrait when resting."] = "休息时在玩家头像旁显示 Zzz 标记。",
    ["PvP Icon"] = "PvP 图标",
    ["The PvP badge by the portrait."] = "头像旁显示 PvP 标志。",
    ["Leader / Role Icons"] = "队长／职责图标",
    ["The leader crown, guide and role icons."] = "显示队长皇冠、队伍引导及职责图标。",
    ["Raid Group Number"] = "团队小队编号",
    ["The Group tag over your frame in a raid."] = "团队模式下，在玩家框体上方显示所属小队编号。",
    ["Rare / Boss / Quest Icons"] = "稀有／首领／任务图标",
    ["The rare star, boss skull and quest badges."] = "显示稀有星形、Boss 骷髅及任务标记。",
    ["Corner Ornament (Player)"] = "玩家头像角落装饰",
    ["The gold piece on the player portrait's corner."] = "设置玩家头像角落的金色装饰。",
    ["Party Frames"] = "队伍框体",
    ["Party Frames Skin"] = "队伍框体风格",
    ["On: CF's look for the party frames, their pets and, in a raid, the raid frames (the rows below). Raid-style party frames only have power bars with the game's Display Power Bars on (Options > Interface > Raid Frames); the power rows show then."] = "开启后，对小队框体、队员宠物及团队框体应用 CF 外观。团队风格的小队框体只有在游戏“设置 → 界面 → 团队框体 → 显示资源条”开启时才显示法力／能量条。",
    ["The art round each portrait and bars."] = "设置头像及进度条周围的装饰。",
    ["Raid-Style Borders"] = "团队样式边框",
    ["The thin lines round each raid-style frame. Crisp Line: ours, a sharp edge with a soft shadow."] = "设置团队样式单位框体周围的细线；“清晰描边”使用锐利边缘及柔和阴影。",
    ["How see-through the party frames are (the raid frames too, in a raid)."] = "设置小队框体的透明度，加入团队后也应用于团队框体。",
    ["The health bars' fill."] = "设置生命条的填充材质。",
    ["Party Health Bar Color"] = "队伍生命条颜色",
    ["Class colours, or Green to Red by health."] = "可以按职业颜色显示生命条，也可根据剩余生命值从绿色逐渐变成红色。",
    ["Health Bar Background"] = "生命条背景",
    ["Behind the health on raid-style frames."] = "团队样式框体的生命条背景。",
    ["The mana / rage / energy bars' fill. Raid-style frames only have a power bar with the game's Display Power Bars on (Options > Interface > Raid Frames); Kingdom Hearts, Fancy Frames and Classic always show power."] = "设置法力、怒气和能量资源条的填充颜色。团队风格的框体需在游戏设置中启用资源条；王国之心、华丽框体和经典风格始终显示资源。",
    ["Muted: mana, rage and energy in softer colours, so health stands out. Raid-style frames only have a power bar with the game's Display Power Bars on (Options > Interface > Raid Frames); Kingdom Hearts, Fancy Frames and Classic always show power."] = "“柔和”模式降低法力、怒气和能量条的颜色饱和度，让生命值更醒目。团队风格框体需在游戏设置中启用资源条；王国之心、华丽和经典框体始终显示资源。",
    ["Party Health / Power Gap"] = "队伍生命条与资源条间距",
    ["Frame Style: Classic: pixels between the health and power bars on each party frame (raid-style or the game's own), as Health / Power Gap does on yours. Left / right."] = "经典框体风格：设置队伍框体生命条与资源条之间的像素间隔，效果类似玩家框体的生命／资源间距。左右方向键调整。",
    ["The names and numbers' font. Your Own Font: as CF Look > Font says."] = "设置姓名和数值字体。自定义字体说明见“CF 外观 → 字体”。",
    ["The names and numbers' size."] = "设置姓名与数值文字大小。",
    ["Names"] = "姓名",
    ["The names over the frames."] = "在框体上显示姓名。",
    ["The names' colour."] = "设置姓名文字颜色。",
    ["Aggro Glow"] = "仇恨高亮",
    ["A slim edge on a member with aggro, in the game's threat colours: yellow or orange when close to pulling or losing it, red with it. Kingdom Hearts: the ring round the face turns that colour. Classic: round the name plate. Hidden: none."] = "为受到仇恨威胁的队友显示细边框，颜色遵循游戏仇恨提示：接近拉怪或丢失仇恨时为黄／橙色，已承受仇恨时为红色。王国之心风格改变头像圆环颜色；经典风格改变姓名板边框；关闭则不显示。",
    ["Leader Icons"] = "队长图标",
    ["The leader crown and guide icon."] = "显示队长皇冠和队伍引导图标。",
    ["Role Icons"] = "职责图标",
    ["The tank / healer / damage icons."] = "显示坦克、治疗及伤害输出职责图标。",
    ["PvP Icons"] = "PvP 标记",
    ["The PvP badges."] = "显示 PvP 状态标记。",
    ["Party Wheel Pick on Frames"] = "在队伍框体标记轮盘选中对象",
    ["On: while the Party Wheel is open, a gold box on the party frame of who you point at."] = "开启队友轮盘时，在当前指向队友的小队框体上显示金色高亮方框。",
    ["Personal Resource Display"] = "个人资源显示",
    ["Personal Resource Display Skin"] = "个人资源条皮肤",
    ["On: CF's look for the game's Personal Resource Display - the health and mana bars under your character (Edit Mode > Personal Resource Display shows or moves them)."] = "开启后，为角色下方的游戏原生个人资源显示（生命条、法力条）应用 CF 外观；可通过编辑模式显示或移动其位置。",
    ["How see-through the bars are."] = "调整进度条透明度。",
    ["The health bar's colour."] = "设置生命条颜色。",
    ["The mana / rage / energy bar's fill (and a druid's mana bar in forms)."] = "设置法力／怒气／能量资源条的填充；也影响德鲁伊变形时的法力条。",
    ["Muted: mana, rage and energy in softer colours, as the Frames skin's."] = "“柔和”模式降低法力、怒气和能量条的颜色饱和度，让生命值更醒目。团队风格框体需在游戏设置中启用资源条；王国之心、华丽和经典框体始终显示资源。",
    ["Bar Background"] = "动作条背景",
    ["Behind each bar: the game's dark frame, a flat dark one, solid black or nothing."] = "进度条背景可选择游戏原生暗框、扁平深色、纯黑色或不显示背景。",
    ["Bar Edge"] = "进度条边缘",
    ["A thin line round each bar."] = "在每个进度条周围绘制细边框。",
    ["Edge Color"] = "边缘颜色",
    ["The thin line's colour (Game's: black)."] = "设置进度条细边线的颜色（游戏默认黑色）。",
    ["The numbers' font. Your Own Font: as CF Look > Font says."] = "设置数字字体，详见“CF 外观 → 字体”的自定义字体说明。",
    ["A dark edge round the numbers."] = "为数字添加深色描边。",
    ["Cast Bar"] = "施法条",
    ["CF Cast Bar"] = "CF 施法条",
    ["On: Controller Forever's cast bar above your buttons, or none at all (the row below). Off: the game's own cast bar."] = "开启后使用 Controller Forever 自定义施法条，可显示在按键上方或隐藏（见下方设置）；关闭后恢复游戏原生施法条。",
    ["CF's slim cast bar above your buttons, or Hidden (no cast bar at all)."] = "在动作按钮上方显示 CF 细施法条；选择“隐藏”则不显示施法条。",
    ["Game's own"] = "游戏原生",
    ["The bar's texture: Classic, Flat, Smooth or Glass."] = "选择施法条填充材质：经典、扁平、平滑或玻璃。",
    ["Classic"] = "经典",
    ["Gold, your class color, or a fixed color."] = "施法条颜色可以选择金色、职业颜色或固定自定义颜色。",
    ["The bright edge that rides the front of the bar."] = "设置施法进度最前沿的高亮光效。",
    ["Spell Icon"] = "法术图标",
    ["The icon of the spell you're casting, left of the bar."] = "在施法条左侧显示正在施放的法术图标。",
    ["Spell Name"] = "法术名称",
    ["The name of the spell on the bar."] = "在施法条上显示正在施放的法术名称。",
    ["Cast Time"] = "施法时间",
    ["Time left, time left and the full cast time, or no numbers."] = "显示剩余施法时间、剩余时间与总时间，或完全隐藏时间数字。",
    ["Channel Ticks"] = "引导技能跳数",
    ["A mark for each tick of a channel, so you can stop between ticks."] = "在引导施法条上标记每一次效果跳数，方便在两次跳数之间决定是否提前结束引导。",
    ["Last Tick in Gold"] = "最后一次跳数用金色标记",
    ["The last tick mark is gold: safe to move on."] = "将最后一次引导效果跳数标记为金色，方便判断何时可以移动。",
    ["Latency Zone"] = "施法延迟区域",
    ["A red zone the size of your ping at the end. Press your next spell when the fill reaches it."] = "在施法进度末端显示按当前网络延迟估算的红色区域；进度进入红区后可以尝试提前输入下一个技能。",
    ["Gray When Out of Range"] = "超出施法距离时变灰",
    ["The bar turns gray while your target is out of range."] = "目标超出施法距离时，施法条变灰。",
    ["Minimap"] = "小地图",
    ["Minimap Skin"] = "小地图皮肤",
    ["On: CF's look for the minimap (the rows below)."] = "开启后为小地图应用下方选择的 CF 外观。",
    ["The map's shape."] = "设置小地图形状。",
    ["Map Dot Size"] = "小地图标记大小",
    ["Size of the dots on the map."] = "调整小地图上标记圆点的大小。",
    ["How see-through the minimap is."] = "调整小地图透明度。",
    ["Zoom Back Out"] = "自动缩回地图",
    ["The map zooms back out by itself after this long."] = "小地图放大后，在设定时间内未操作就自动缩回。",
    ["Never"] = "从不",
    ["The edge round the map."] = "设置小地图边框。",
    ["The border's colour."] = "设置边框颜色。",
    ["Border Pulse"] = "边框呼吸光效",
    ["Glow or Neon border: it slowly pulses."] = "边框采用发光或霓虹风格时，显示缓慢呼吸光效。",
    ["Border Spin"] = "边框旋转",
    ["A round border turns."] = "使圆形小地图边框缓慢旋转。",
    ["Zone Name"] = "地区名称",
    ["The zone name bar over the map."] = "设置小地图上方的地区名称栏。",
    ["Zone Name Color"] = "地区名称颜色",
    ["The zone name's colour."] = "设置地区名称文字颜色。",
    ["Clock"] = "时钟",
    ["The clock on the minimap."] = "设置小地图时钟。",
    ["Clock Color"] = "时钟颜色",
    ["The clock's and coordinates' colour."] = "设置时钟和坐标数字的颜色。",
    ["Coordinates"] = "坐标",
    ["Your map coordinates on the minimap."] = "在小地图上显示当前地图坐标。",
    ["Frame Rate & Ping"] = "帧率与网络延迟",
    ["Frame rate and ping on the map."] = "在小地图上显示帧率与网络延迟。",
    ["Zone & Clock Boxes"] = "地区名称与时钟背景框",
    ["Zone name and clock in small dark boxes. Experimental."] = "在小型暗色方框中显示地区名称和时钟（实验性）。",
    ["Size of the zone name, clock and coordinates."] = "调整地区名称、时钟与坐标的大小。",
    ["Zoom Buttons"] = "缩放按钮",
    ["The + / - zoom buttons: on mouse over, always, or hidden."] = "缩放按钮（＋／－）可设置为鼠标悬停时显示、始终显示或隐藏。",
    ["Mouse Over"] = "鼠标悬停",
    ["Calendar Button"] = "日历按钮",
    ["The calendar button by the map."] = "小地图旁的日历快捷按钮。",
    ["Tracking Button"] = "追踪按钮",
    ["The tracking button by the map."] = "小地图旁的追踪快捷按钮。",
    ["Mail Icon"] = "新邮件图标",
    ["The new-mail icon by the map."] = "有新邮件时在小地图旁显示邮件图标。",
    ["Dungeon Difficulty"] = "地下城难度",
    ["The dungeon difficulty flag on the map."] = "在小地图上显示地下城难度标记。",
    ["Other Addons' Buttons"] = "其他插件的小地图按钮",
    ["The buttons other addons put round the minimap."] = "控制其他插件放在小地图周围的按钮显示。",
    ["Who Pinged"] = "谁发送了地图信号",
    ["Who pinged the minimap shows for a few seconds."] = "小地图被队友标记时，短暂显示发送信号的玩家。",
    ["Chat Skin"] = "聊天窗口皮肤",
    ["On: CF's look for the chat (the rows below)."] = "开启后，为聊天窗口应用下方的 CF 外观设置。",
    ["How see-through the chat is."] = "设置聊天窗口透明度。",
    ["Fade When Quiet"] = "无消息时淡出",
    ["The whole chat fades out after this long with nothing new said. A new line, or opening it to type, brings it back."] = "若长时间没有新消息，聊天窗口自动淡出；收到新消息或打开输入框时重新显示。",
    ["Text Fades Out"] = "聊天文字自动淡出",
    ["How long each line stays before it fades out on its own (the game's own fade)."] = "设置聊天消息在自动淡出前保留的时间（使用游戏原生淡出效果）。",
    ["Background"] = "背景",
    ["Behind the chat: the game's, none, a colour, or a fade."] = "聊天窗口背景可选择游戏原生、无背景、纯色或渐变。",
    ["Background Color"] = "背景颜色",
    ["The background's colour."] = "设置背景颜色。",
    ["Background Opacity"] = "背景不透明度",
    ["How solid the background is."] = "调整聊天背景的不透明度。",
    ["Background Shows"] = "背景显示时机",
    ["Always, or only with the pointer over the chat."] = "选择始终显示背景，或仅在鼠标指针悬停聊天窗口时显示。",
    ["Always"] = "始终",
    ["A frame round the chat."] = "在聊天窗口周围显示边框。",
    ["The chat text font. Your Own Font: as CF Look > Font says."] = "设置聊天文字字体。自定义字体说明见“CF 外观 → 字体”。",
    ["Font Size"] = "字体大小",
    ["The chat text size, every window."] = "调整所有聊天窗口的文字大小。",
    ["Text Shadow"] = "文字阴影",
    ["The shadow under the letters."] = "在聊天文字下方显示阴影。",
    ["Timestamps"] = "聊天时间戳",
    ["The time in front of each line."] = "在每条聊天消息前显示时间。",
    ["Class Colored Names"] = "职业颜色显示姓名",
    ["Player names in their class colour."] = "按玩家职业颜色显示姓名。",
    ["Chat Tabs"] = "聊天标签页",
    ["The General / Combat Log tabs."] = "控制“综合”和“战斗记录”标签页。",
    ["Game's (Fade)"] = "游戏原生（自动淡出）",
    ["Tab Flash"] = "新消息时闪烁标签",
    ["A tab flashes with a new message."] = "标签页收到新消息时闪烁提示。",
    ["Tab Look"] = "标签页外观",
    ["Flat: plain dark tabs with an accent line under the one you are on. Experimental."] = "扁平样式：使用深色标签页，并在当前标签页底部添加强调色线条（实验性）。",
    ["Typing Box"] = "聊天输入框",
    ["Where the typing box sits."] = "设置聊天输入框的位置。",
    ["Below (Game's)"] = "下方（游戏原生）",
    ["Typing Box Look"] = "聊天输入框外观",
    ["The typing box's frame."] = "设置聊天输入框边框。",
    ["Chat Buttons"] = "聊天快捷按钮",
    ["The menu, channel and friends buttons by the chat."] = "显示聊天窗口旁的菜单、频道和好友按钮。",
    ["Scroll Bar"] = "滚动条",
    ["The scroll bar and Jump to Bottom button."] = "显示滚动条与“跳到最底部”按钮。",
    ["Bags"] = "背包",
    ["CF Bags"] = "CF 整合背包",
    ["On: Controller Forever's own bag window, one window with all your bags, made for the controller - grouped into New, Quest, Use, Gear, Trade Goods, Other and Junk. A picks up, X uses or equips, Y has more. It opens wherever your bags open - at a vendor, the bank, the mailbox, trade and the Auction House too, where X sells, moves, attaches or posts (LT goes over to the game's window, RT back) - and in a fight, where the D-pad moves, X uses and B closes. Start in it has its options. Off: the game's own bags, with the Bags skin if you like."] = "开启后使用针对手柄设计的 CF 整合背包，把所有背包合并为一个窗口，按“新物品、任务、可使用、装备、交易物品、其他、垃圾”分类。A 拿起物品、X 使用或装备、Y 查看更多；在商人、银行、邮箱、交易和拍卖行打开背包时，同样使用此窗口，X 根据场景执行出售、存取、附加或上架。可用 LT 切到游戏窗口、RT 切回背包；战斗中方向键浏览，X 使用，B 关闭。按 Start 可打开背包设置。关闭后使用游戏原生背包，并可继续使用 CF 背包皮肤。",
    ["Bags Skin"] = "背包皮肤",
    ["On: CF's touches for the game's bags (the rows below)."] = "开启后为游戏原生背包应用下方指定的 CF 界面效果。",
    ["Bag Icons"] = "背包图标",
    ["Together on Top: all the bag icons in the first row."] = "将所有背包图标集中显示在第一行顶部。",
    ["Game's (Before Each Bag)"] = "游戏原生（显示在各背包前）",
    ["Empty Slots"] = "空栏位",
    ["At the End: items first, every empty slot after."] = "将背包内物品排在前面，把全部空栏位集中放在最后。",
    ["Game's Order"] = "游戏原生顺序",
    ["Bag Buttons"] = "背包按钮",
    ["The backpack and bag buttons on screen."] = "控制屏幕上的背包和背包栏位按钮。",
    ["Free Slots"] = "剩余空栏位",
    ["How many empty slots you have, over the bag."] = "在背包上方显示剩余空栏位数量。",
    ["Quick Bank Moves"] = "银行物品快捷移动",
    ["On: at a banker, X moves the item the game's cursor is on to the bank, or back to your bags, in one press. With the game's bags (CF Bags has its own bank screen)."] = "开启后，与银行 NPC 对话时，按 X 可以把当前光标物品一键移入银行，或从银行取回背包。此功能适用于游戏原生背包，CF 整合背包有专门的银行界面。",
    ["Bags: Layout"] = "背包：布局",
    ["Full Window: one big window in the middle of the screen, the item you're on described beside your items. Simple: a small window where the game's bags open, bottom right, with all your items in it and the game's own tooltip beside it."] = "完整窗口：在屏幕中央显示大型整合背包，并在旁边显示当前选中物品的说明。简易窗口：在原生背包的右下角位置显示小型整合背包，并使用游戏原生物品提示框。",
    ["Full Window"] = "完整窗口",
    ["Bags: Order"] = "背包：排序方式",
    ["By Kind: New, Quest, Use, Gear, Trade Goods, Other, Junk. Bag by Bag: each bag in turn. One Bag: every item in one grid as your bags hold them, backpack first - no sections, no bags - the empty slots at the end."] = "按类型：新物品、任务、可使用、装备、交易物品、其他、垃圾。按背包：依次显示各个背包。单一网格：按背包原有顺序将全部物品排成一张网格，主背包在前，不显示分类及背包分隔，空栏位集中在最后。",
    ["By Kind"] = "按种类",
    ["Bags: Item Level"] = "背包：物品等级",
    ["The item level on weapons and armor. It starts as your Bags skin's Item Level row has it."] = "在武器和护甲上显示物品等级，初始设置与背包皮肤中的“物品等级”一致。",
    ["Bags: Item Level Color"] = "背包：物品等级颜色",
    ["The item level in white, or in the item's quality colour (green, blue, purple). It starts as your Bags skin has it."] = "物品等级可显示为白色或按品质显示为绿、蓝、紫色；初始设置跟随背包皮肤。",
    ["Bags: Upgrade Marks"] = "背包：装备提升标记",
    ["A green arrow on gear better for you than what you wear, a red X on worse (the same check as Loot Rolls)."] = "与身上装备相比，更好的装备显示绿色箭头，更差的显示红色叉号（使用与拾取掷骰相同的评估逻辑）。",
    ["Bags: New Item Glow"] = "背包：新物品高亮",
    ["The glow on items you got since you last looked. It starts as your Bags skin's New Item Glow row has it."] = "上次打开背包后新获得的物品会发光，初始设置沿用背包皮肤中的“新物品高亮”。",
    ["Bags: Junk Coin"] = "背包：灰色垃圾金币标记",
    ["A coin on gray junk, wherever it sits. It starts as your Bags skin has it."] = "在灰色垃圾物品上显示金币标记，无论其位于哪个背包；初始设置沿用背包皮肤。",
    ["Bags: Edge Color"] = "背包：物品边框颜色",
    ["The edge round each item: its quality colour, your CF Look's colour, or black. It starts as your Bags skin has it."] = "物品边框可使用品质颜色、当前 CF 主题色或黑色；初始设置沿用背包皮肤。",
    ["Item's Quality"] = "物品品质",
    ["Bags: Edge Thickness"] = "背包：物品边框粗细",
    ["How thick the edge round each item is. It starts as your Bags skin has it."] = "设置每个物品图标的边框粗细，初始设置沿用背包皮肤。",
    ["Item Level"] = "物品等级",
    ["The item level on weapons and armor."] = "在武器与护甲上显示物品等级。",
    ["Item Level Color"] = "物品等级颜色",
    ["The item level in white, or the item's quality colour. Experimental."] = "物品等级可显示为白色或对应品质颜色（实验性）。",
    ["Compare to Equipped"] = "与已装备物品比较",
    ["A green arrow on gear better for you than what you wear, a red X on worse. Experimental."] = "比当前装备更合适的物品显示绿色箭头，更差的显示红色叉号（实验性）。",
    ["Junk"] = "垃圾物品",
    ["Gray junk is darkened, with a coin on it."] = "灰色垃圾物品图标变暗，并显示金币标记。",
    ["New Item Glow"] = "新物品高亮",
    ["The sparkle on new items. Experimental."] = "新获得的物品显示高亮光效（实验性）。",
    ["Slot Look"] = "物品栏位外观",
    ["Flat: no slot frames, a thin edge in the item's quality colour. Experimental."] = "扁平样式：隐藏原有栏位边框，改用物品品质颜色细边线（实验性）。",
    ["Edge Thickness"] = "边框粗细",
    ["Flat slots: how thick each item's edge is. Experimental."] = "设置扁平样式下物品图标边缘的线条粗细（实验性）。",
    ["Flat slots: the edge colour. Experimental."] = "设置扁平样式下物品边缘颜色（实验性）。",
    ["Window Color"] = "窗口颜色",
    ["The bag window's background. Experimental."] = "设置背包窗口背景颜色（实验性）。",
    ["Window Background Opacity"] = "窗口背景不透明度",
    ["How see-through that background is. Experimental."] = "设置背景透明度（实验性）。",
    ["How see-through the open bags are."] = "调整打开背包窗口时的透明度。",
    ["Damage Meter"] = "伤害统计",
    ["CF Meter"] = "CF 统计面板",
    ["On: Controller Forever's damage meter panel in place of the game's - DPS, damage, healing and more, class-coloured bars, your own row always on it with a gold edge. Display only; it keeps going in fights. Off: the game's own damage meter. (The game's meter isn't there for this character yet.)"] = "开启后，使用 CF 自带的伤害统计面板替代游戏原生统计。支持 DPS、总伤害、治疗量等指标，按职业颜色绘制条形，自己的数据始终显示并带金色边框。只负责显示，不影响战斗统计。关闭后使用游戏原生统计（如果当前客户端有该功能）。",
    ["Damage Meter Skin"] = "统计面板皮肤",
    ["On: CF's look for the damage meter (the rows below)."] = "开启后将下方 CF 外观应用于伤害统计面板。",
    ["How see-through the meter is."] = "调整伤害统计面板透明度。",
    ["Title Bar"] = "标题栏",
    ["The bar along the top of the meter."] = "设置统计面板顶部的标题栏。",
    ["The scroll bar on the side."] = "设置侧边滚动条。",
    ["CF's Meter: Shows"] = "CF 统计面板：显示指标",
    ["DPS, Damage, Healing, HPS, Damage Taken, Deaths or Threat (your group's threat on your target). Left / right."] = "可选择 DPS、总伤害、治疗量、HPS、承受伤害、死亡次数或仇恨（小队对当前目标的仇恨）。左右方向键切换。",
    ["DPS"] = "每秒伤害（DPS）",
    ["CF's Meter: Rows"] = "CF 统计面板：显示行数",
    ["How many players it shows (3 to 10). Your own row is always one of them."] = "设置显示 3–10 名玩家，自己的数据始终保留在列表中。",
    ["CF's Meter: Opacity"] = "CF 统计面板：透明度",
    ["How solid the panel is. 100 solid, 0 invisible."] = "设置面板不透明度：100 完全显示，0 完全透明。",
    ["CF's Meter: Second Meter"] = "CF 统计面板：第二面板",
    ["On: a second meter panel beside the first, showing something else at the same time - Threat at first (your group's threat on your target), or any of the others. Its own spot and size in Edit Layout; Rows and Opacity are the first one's."] = "开启后，在第一块伤害统计面板旁再显示一块，可同时查看不同指标。默认显示当前目标的队伍仇恨，也可选择其他数据。第二块面板可独立设置位置和尺寸，但行数与透明度沿用第一块面板。",
    ["CF's Meter: Second Shows"] = "CF 统计面板：第二面板指标",
    ["What the second panel shows: Threat, DPS, Damage, Healing, HPS, Damage Taken or Deaths. Left / right."] = "选择第二面板显示仇恨、DPS、总伤害、治疗、HPS、承受伤害或死亡次数。左右方向键切换。",
    ["Threat"] = "仇恨",
    ["CF's Meter: Move the Second Meter"] = "移动第二统计面板",
    ["The look of each bar's fill."] = "设置统计条填充材质。",
    ["Bar Color"] = "动作条颜色",
    ["One colour for every bar."] = "所有统计条使用统一颜色。",
    ["Behind each bar's fill."] = "设置统计条填充区域的背景。",
    ["The edge round each bar."] = "设置每个统计条的边框。",
    ["Zebra Stripes"] = "隔行底色",
    ["Every other bar a little lighter."] = "每隔一行使用稍浅的颜色，方便区分。",
    ["Highlight #1"] = "高亮第一名",
    ["A gold edge on the top bar."] = "在排名第一的统计条周围显示金色边框。",
    ["The names' and numbers' font. Your Own Font: as CF Look > Font says."] = "设置玩家姓名和统计数字字体。自定义字体说明见“CF 外观 → 字体”。",
    ["The players' names."] = "显示玩家姓名。",
    ["Number Color"] = "数字颜色",
    ["The damage / healing numbers."] = "伤害／治疗统计数值。",
    ["Window Background"] = "窗口背景",
    ["Behind the whole meter."] = "设置统计面板整体背景。",
    ["The window background's colour."] = "设置窗口背景颜色。",
    ["A frame round the meter."] = "设置统计面板外边框。",
    ["Auction House"] = "拍卖行",
    ["CF Auction House"] = "CF 手柄拍卖行",
    ["On: Controller Forever's own Auction House window, made for the controller (whole item names as you type, buy and post with A, your undercut auctions first). Start in it has its options. Off: the game's own Auction House window."] = "开启后使用 CF 的手柄拍卖行窗口：支持输入完整物品名称、按 A 购买或上架，并优先显示可压价竞争的拍卖。按 Start 打开选项。关闭后恢复游戏原生拍卖行窗口。",
    ["Keyboard in the Game's AH"] = "原生拍卖行输入键盘",
    ["On: in the game's own Auction House, pressing A with the controller on the search box or a gold, silver, copper or quantity box opens CF's keyboard. Start puts what you typed in that box (numbers only in a number box), B leaves it as it was; then press the game's Search or Post as usual. Off: the game's way."] = "在游戏原生拍卖行中，选中搜索框或金币、银币、铜币、数量输入框后按 A，会打开 CF 手柄输入键盘。按 Start 提交输入（数字框只能输入数字），按 B 保留原内容；然后照常使用游戏“搜索”或“上架”按钮。关闭后使用原生输入方式。",
    ["Keyboard in the Mailbox"] = "邮箱输入键盘",
    ["Mail Keyboard"] = "邮件输入键盘",
    ["On: at the mailbox's Send Mail, pressing A with the controller on To, Subject, the letter or a gold, silver or copper box opens CF's keyboard. Start puts what you typed in that box (numbers only in a money box), B leaves it as it was; then press the game's Send as usual. Off: the game's way."] = "在邮箱的“发送邮件”界面中，选中收件人、主题、正文或金币／银币／铜币输入框后按 A，会打开 CF 手柄键盘。按 Start 确认输入（金额框仅可输入数字），按 B 保留原内容；之后照常按游戏“发送”。关闭后使用原生输入方式。",
    ["To"] = "收件人",
    ["Subject"] = "主题",
    ["Letter"] = "邮件正文",
    ["AH: Buying"] = "拍卖行：购买操作",
    ["One press of A buys anything under your limit, A again over it; or always A again."] = "低于限价的物品按一次 A 即可购买，高于限价则需再按一次确认；也可设置为始终二次确认。",
    ["One press under your limit"] = "低于限价时单按购买",
    ["AH: One-Press Buy Limit"] = "拍卖行：单按购买限价",
    ["The most one press of A spends in the Controller Auction House; pricier buys ask for A again. Left / right: 1g a step."] = "在 CF 手柄拍卖行中，低于此金额的物品按一次 A 即可购买；超过限额时需再按 A 确认。左右方向键每次调整 1 金币。",
    ["AH: Auction Duration"] = "拍卖行：默认上架时长",
    ["How long your auctions stay up unless you pick another time on the Post sheet (a longer time costs a bigger deposit)."] = "设置拍卖的默认上架时长。可在上架页面另行指定；时间越长，保证金越高。",
    ["AH: Back Buttons"] = "拍卖行：背键",
    ["In the Controller Auction House the back buttons jump to the previous / next section of a list, or work as left and right."] = "在 CF 手柄拍卖行中，背键可跳转到列表上一个／下一个分区，也可设置为左右方向键。",
    ["Jump between sections"] = "在不同分区间快速切换",
    ["AH: Gold as Text"] = "拍卖行：金币使用文字显示",
    ["Prices as 3g 30s 40c instead of coin pictures, easier to read from the couch."] = "将价格显示为 3g 30s 40c 文字，而不是金币图标，便于远距离阅读。",
    ["AH: Game's Tooltip Too"] = "拍卖行：同时显示原生物品提示",
    ["The game's own item tooltip and compare beside the Controller Auction House window too (it covers part of the list)."] = "同时显示游戏原生物品提示及装备比较框；可能遮挡拍卖行列表的一部分。",
    ["AH: Window Size"] = "拍卖行：窗口大小",
    ["The Controller Auction House window's size, 80 to 110 %."] = "调整 CF 手柄拍卖行窗口大小（80%–110%）。",
    ["Loot Rolls"] = "战利品掷骰",
    ["CF Loot Rolls"] = "CF 战利品掷骰窗口",
    ["On: Controller Forever's roll window - every item with its timer, Select picks it, A / X / B / Y roll. Off: the game's own roll window, left as the game has it. Change it out of a fight, with no roll up."] = "开启后使用 CF 的战利品掷骰窗口：每件物品都显示剩余时间，用 Select 选中物品，A／X／B／Y 执行对应掷骰选项。关闭后恢复游戏原生掷骰窗口。只能在非战斗、没有进行中的掷骰时修改。",
    ["Blizzard Art"] = "游戏原生装饰",
    ["Show Blizzard Art"] = "显示游戏原生动作条装饰",
    ["On: the game's gryphons sit at the ends of your bars. Move and size each one in Edit Layout."] = "在动作条两端显示游戏原生的狮鹫装饰，可在“编辑布局”中移动并缩放。",
    ["Blizzard Art Style"] = "游戏原生装饰风格",
    ["Blizzard Art Size"] = "原生装饰尺寸",
    ["Both sides bigger or smaller together. Left / right. LT / RT in Edit Layout sizes one."] = "左右装饰同时缩放，使用左右方向键调整；在编辑布局中可以用 LT／RT 调整单侧。",
    ["Flip Blizzard Art"] = "翻转原生装饰",
    ["On: each side faces the other way."] = "开启后，将两侧的装饰图案翻转朝向。",
    ["Accent, font and border"] = "主题色、字体与边框",
    ["Player and target frames"] = "玩家与目标框体",
    ["Party frame skin"] = "小队框体皮肤",
    ["Bars under your character"] = "角色下方的资源条",
    ["Your cast bar's look"] = "施法条外观",
    ["Minimap skin"] = "小地图皮肤",
    ["Chat skin"] = "聊天窗口皮肤",
    ["CF Bags, or skin the game's"] = "使用 CF 整合背包，或美化原生背包",
    ["CF Meter, or skin the game's"] = "CF 统计面板或游戏原生统计皮肤",
    ["One look for every skin."] = "所有皮肤使用统一外观。",
    ["Text"] = "文字",
    ["Fonts for the skins and all game text."] = "调整界面皮肤和全部游戏文字的字体。",
    ["Ready-Made"] = "预设外观",
    ["All Text Font"] = "全部文字字体",
    ["All Text Size"] = "全部文字大小",
    ["Menu and Windows"] = "菜单和窗口",
    ["CF's own menu and windows: their look, whatever your skins."] = "独立调整 CF 自带菜单及窗口的外观，不受其他皮肤设置影响。",
    ["Gold as Text"] = "金币文字显示",
    ["Game's Tooltip"] = "游戏原生提示框",
    ["Window Size"] = "窗口大小",
    ["CF Window"] = "CF 窗口",
    ["The row you're on"] = "当前选中的条目",
    ["Drawn by the window itself, with sample items. Live: open your bags."] = "显示示例物品的窗口预览；若想查看实时效果，请打开背包。",
    ["Nothing matches your search."] = "没有符合搜索条件的内容。",
    ["since you last looked"] = "自上次查看以来",
    ["never sold"] = "从未售出",
    ["uses it"] = "使用此物品",
    ["better"] = "更好",
    ["worse than worn"] = "比当前装备更差",
    ["most first"] = "数量最多的优先",
    ["%d empty slots"] = "%d 个空栏位",
    ["New"] = "新物品",
    ["Quest"] = "任务",
    ["Use"] = "可使用",
    ["Gear"] = "装备",
    ["Trade Goods"] = "交易物品",
    ["Other"] = "其他",
    ["sells for %s"] = "售价 %s",
    ["IN A FIGHT"] = "战斗中",
    ["It stays: the D-pad moves, X uses, B closes. Picking up and More wait for its end."] = "战斗中仍能用十字方向键浏览物品、按 X 使用、按 B 关闭；拿起物品及“更多”操作需脱战后进行。",
    ["Order: %s"] = "排序方式：%s",
    ["Clean Up"] = "整理",
