    ["Rolling"] = "战利品掷骰",
    ["Gryphons at your bars' ends"] = "动作条两端的狮鹫装饰",
    ["Edit Layout: Start"] = "编辑布局：Start",
    ["On: Start is yours to bind. With nothing bound on a modifier it still opens the Start menu. On (hidden): works, not drawn."] = "开启后可自定义 Start 键。若当前组合层没有绑定，则仍能打开 Start 菜单；“开启（隐藏）”时功能有效但不显示按钮。",
    ["Start as a button of your own."] = "将 Start 设为可自定义的独立按键。",
    ["Edit Layout: Both Stick Clicks"] = "编辑布局：左右摇杆按下键",
    ["Edit Layout: L3"] = "编辑布局：L3",
    ["Edit Layout: R3"] = "编辑布局：R3",
    ["L3 / R3 Action Buttons"] = "L3／R3 动作按钮",
    ["Click a stick to fire your own bind, one per modifier. On, or On (hidden): they work, not drawn."] = "按下摇杆可执行自定义绑定，每个组合层都能设置独立动作。“开启（隐藏）”模式下功能仍有效，但不显示按钮。",
    ["Click a stick for a bind of your own."] = "按下摇杆（L3／R3）执行自定义绑定。",
    ["Own Buttons"] = "独立按键",
    ["Targeting Method"] = "目标选择方式",
    ["LB / RB: Target Nearest Friend on LB and Target Nearest Enemy on RB (Controller Forever asks first). LT / RT: Tab Targeting (tap RT: the next enemy, tap LT: the next friend), LB / RB free for your own spells."] = "LB／RB 模式：LB 选择最近的友方目标，RB 选择最近的敌方目标（CF 会先确认）。LT／RT 模式：短按 RT 切换下一个敌人，短按 LT 切换下一个友方；LB／RB 可以留给自己的技能绑定。",
    ["LT / RT (Tab Targeting)"] = "LT／RT（Tab 目标选择）",
    ["Interact, Else Tab Target"] = "优先交互，否则切换目标",
    ["Ground Spells"] = "地面范围法术",
    ["Rain of Fire, Blizzard and the like. Press Twice: the game's way. At Your Target: one press drops it on the enemy you target (no enemy targeted: see With No Target; Healing Rain and the like on a friend too). At the Crosshair: one press drops it where the crosshair points. Bombs and grenades too: At the Crosshair throws one at once, At Your Target onto your enemy target (no enemy: as With No Target says), and Press Twice shows its green circle at the crosshair - turn the camera to move it, the same button again throws it (Bombs and Grenades, under it, gives bombs Press Twice on their own). Pet Move To: press shows the circle at the crosshair, press again to send your pet - the game won't let it go in one press. Pressing again works on A / B / X / Y, the D-pad and the back buttons (back buttons sent as keyboard keys: out of a fight only)."] = "火焰之雨、暴风雪等地面指向技能：“按两次”沿用游戏原生方式；“对当前目标施放”按一次即向目标落点施法（没有敌方目标时按“无目标时”设置处理，治疗之雨等可作用于友方）；“准星位置”则在屏幕准星所指位置施放。炸弹和手榴弹同理：准星模式直接投掷，对目标模式投向当前敌人；双按模式先显示绿色落点圆圈，转动镜头调整后再按同一按键投掷。宠物移动命令仍需两次按键：先显示目的地圆圈，再确认移动。再次按键功能适用于 A／B／X／Y、十字方向键和背键；背键作为键盘输入时仅非战斗可用。",
    ["Press Twice"] = "按两次",
    ["With No Target"] = "没有有效目标时",
    ["Only with Ground Spells: At Your Target. When you have no enemy targeted (or Healing Rain and the like: no one), the press drops it At the Crosshair, Doesn't Cast at all, or Shows the Circle for a second press (the game's way)."] = "仅当“地面法术 → 对当前目标施放”生效时使用。如果没有敌对目标（或治疗之雨等没有友方目标），可选择在准星位置施放、完全不施放，或先显示落点圆圈等待第二次确认。",
    ["At the Crosshair"] = "在准星位置",
    ["Grenade Choice"] = "手榴弹选择方式",
    ["Which bomb, grenade or dynamite your Grenade bind (All Keybinds > Game Actions) throws. Best: the strongest you carry. Weakest First: the weakest, to save the good ones. Most in Bags: the one you have the most of. It picks again when your bags change and when a fight ends, and throws the way Ground Spells (or Bombs and Grenades) says."] = "设置“全部按键绑定 → 游戏操作”中的手榴弹快捷键使用哪种爆炸物。“最强优先”选择携带的最高强度炸弹；“最弱优先”先使用低级炸弹保留高级物品；“背包最多”优先使用数量最多的类型。背包内容变化或战斗结束后会重新选择，投掷方式遵循“地面法术／炸弹与手榴弹”设置。",
    ["Best"] = "优先最强",
    ["Put Grenade on a Button"] = "将投掷手榴弹绑定到按键",
    ["Press the button you want the Grenade bind on (any button, with or without LT / RT). It throws the grenade Grenade Choice picks, the way Ground Spells (or Bombs and Grenades) says."] = "按下希望用于投掷手榴弹的手柄按键，可选择是否带 LT／RT 组合层。快捷键将使用“手榴弹选择”确定的弹药，施放方式遵循地面法术或爆炸物设置。",
    ["Healing Potion Choice"] = "治疗药水选择方式",
    ["Put Healing Potion on a Button"] = "绑定治疗药水",
    ["Mana Potion Choice"] = "法力药水选择方式",
    ["Put Mana Potion on a Button"] = "绑定法力药水",
    ["Put Best Food on a Button"] = "绑定最佳食物",
    ["Put Best Water on a Button"] = "绑定最佳饮水",
    ["Put Eat and Drink on a Button"] = "绑定吃喝",
    ["Best Food"] = "最佳食物",
    ["Best Water"] = "最佳饮水",
    ["Eat and Drink"] = "吃东西与喝水",
    ["Bombs and Grenades"] = "炸弹与手榴弹",
    ["Press Twice: a bomb, grenade or dynamite shows its green circle where your crosshair points - turn the camera to move it, then press the same button again to throw it. Spells keep Ground Spells. Like Ground Spells: bombs go the way Ground Spells says. Works on A / B / X / Y, the D-pad and the back buttons (sent as keyboard keys: out of a fight only), and for the Grenade bind."] = "双按投掷：第一次按下后，在准星位置显示绿色落点圆圈；转动镜头调整位置，再按同一按键投出。法术仍按“地面法术”设置执行。“按地面法术方式”让爆炸物沿用相同规则。适用于 A／B／X／Y、十字方向键及背键（映射为键盘输入的背键仅非战斗有效），以及独立手榴弹快捷键。",
    ["Like Ground Spells"] = "使用地面法术的施放方式",
    ["Icons on Screen"] = "屏幕按键图标",
    ["Edit Layout: LT / RT Target Icons"] = "编辑布局：LT／RT 目标图标",
    ["Opens Edit Layout on the LT / RT target icons: the D-pad moves them, LT / RT size them, X then left / right moves them in / out, hold Y puts them back. B is done."] = "打开 LT／RT 目标图标布局编辑：方向键移动位置，LT／RT 调整大小；按 X 后用左右方向键调整水平位置；长按 Y 重置。按 B 完成。",
    ["Show LT / RT Target Icons"] = "显示 LT／RT 目标图标",
    ["Shown: the green friend / red enemy dots by your bar while LT / RT target. Hidden: not drawn; the taps still target."] = "显示：使用 LT／RT 选择目标时，在动作条旁显示绿色友方／红色敌方指示点。隐藏：不显示图标，但按键仍可选取目标。",
    ["Show LB / RB Target Icons"] = "显示 LB／RB 目标图标",
    ["Hidden: LB / RB aren't drawn while they hold Target Nearest Friend / Enemy. They still target."] = "隐藏后，LB／RB 作为“选择最近友方／敌方”时不显示按钮图标，但目标选择仍可正常使用。",
    ["Taps"] = "短按操作",
    ["Tap to Lock a Trigger"] = "短按锁定扳机键",
    ["On: tap LT or RT and its modifier stays on until you tap again. Held while you press a button, it's a normal hold."] = "开启后，短按 LT 或 RT 会锁定对应组合层，再按一次解除；持续按住扳机键并按其他键仍按正常长按方式工作。",
    ["Not With LT / RT Targeting"] = "与 LT／RT 目标选择模式互斥",
    ["Cancel the Lock After a Cast"] = "施法后解除锁定",
    ["On: with a trigger locked, the next button you press uses that set, then the lock comes off."] = "开启后，锁定扳机键的下一次按键将使用该组合层，然后自动解除锁定。",
    ["Stick Targeting"] = "摇杆方向选目标",
    ["On (LT / RT)"] = "开启（LT／RT）",
