    ["4 min"] = "4 分钟",
    ["6 min"] = "6 分钟",
    ["Set Up Your Important Default Binds"] = "设置重要默认按键",
    ["The default binds - Jump, Interact, the wheels, the map and more - one by one beside All Keybinds: bind each, pick another button or skip."] = "依次设置跳跃、交互、轮盘、地图等默认快捷操作；可为每项选择按键，也可跳过。",
    ["Set up your controller, find your way round the menu, move and talk."] = "完成手柄基本设置，熟悉菜单、移动和 NPC 交互。",
