    ["Pick a ready-made look, or make every part your own."] = "选择预设外观，也可以逐项自定义。",
    ["Heal and buff your party from the controller, your enemy still targeted."] = "通过手柄治疗和给队友补增益，同时保持敌方目标不变。",
