    ["A, then press "] = "按 A 后，再按： ",
    ["A: a code with your setup to paste to a friend. Left / right: settings, binds or both."] = "按 A 生成可分享给朋友的配置代码。左右方向键选择导出设置、按键绑定或全部内容。",
    ["A: hide this from "] = "按 A 从以下位置隐藏此项： ",
