    ["A: load this save (reloads). X: rename it. Binds and macros stay."] = "按 A 加载存档并重新加载界面，按 X 重命名。按键绑定与宏不会改变。",
    ["A: on your sell list (sold at every merchant) or off it."] = "按 A 将此物品加入或移出“自动出售清单”；在 NPC 商人处会按清单自动出售。",
    ["A: sells everything below that isn't marked Keep, one at a time."] = "按 A 逐件出售下方未标记为“保留”的物品。",
    ["A: takes it off your sell list."] = "按 A 将物品从自动出售清单中移除。",
    ["A: this picture for "] = "按 A 将此图标用于： ",
    ["Above the Cast Bar"] = "施法条上方",
    ["Accent"] = "主题强调色",
    ["Actions"] = "操作",
    ["Add a Bar"] = "添加动作条",
    ["Add an emote"] = "添加表情动作",
    ["Add something"] = "添加内容",
    ["Addon Buttons"] = "插件按钮",
    ["After eating, a small stick nudge will not stand you up."] = "进食期间轻微触碰摇杆不会让角色站起来。",
    ["All (gray when missing): every buff it watches, grayed while it's missing, bright with its time left while it's on. Only Missing: just the ones not on you, with a red edge - each goes as you put it on. In a fight the game hides your buffs from addons, so Only Missing then shows every one it watches: red edge = missing, dark and faded = on. A or left / right: switch."] = "“全部（缺失时置灰）”：始终显示所有监控中的增益，缺失时变灰，存在时高亮并显示剩余时间。“仅显示缺失”：只显示当前身上没有的增益，并加上红色边框；补上增益后图标会消失。战斗中游戏可能限制插件读取增益状态，此时“仅显示缺失”也会显示全部监控项：红框表示确实缺失，暗淡表示已存在。按 A 或左右方向键切换。",
    ["All Items"] = "全部物品",
    ["All Keybinds on its Extra Bars page, at "] = "前往“全部按键绑定 → 额外动作条”设置： ",
