    ["Game's: the game's own look and frames, every CF skin off (your skin rows are kept for when you turn one on again). Clean Dark: every skin on, in flat dark panels with thin edges - one pick, used as it is. Kingdom Hearts / Fancy Frames: that Frame Style with every skin on, yours to change. Classic: everything that has a classic look - Frame Style, Minimap, Window Style and the bar textures (the game reloads). Make It My Own: every skin on, yours to change on their cards."] = "“游戏原生”：关闭全部 CF 皮肤，恢复游戏默认界面，但保留你的皮肤设置以供再次启用。“简洁深色”：使用扁平暗色背景与细边框，所有皮肤统一应用。“王国之心／华丽框体”：采用对应框体风格，并允许进一步修改各模块。“经典”：使用经典框体、小地图、窗口样式及进度条材质，游戏会重新加载。“自定义”：启用所有皮肤模块，可在各设置页逐项调整。",
