    ["Left / right: Compact (one bar of buttons, changing as you hold LT / RT), Final Fantasy (every modifier's bar at once)"] = "左右方向键选择“紧凑”（按 LT／RT 切换单条动作条）或“FF 风格”（全部组合层动作条同时显示）",
