    ["Mana / rage / energy bars under the raid-style party frames. This is the game's own Display Power Bars (Options > Interface > Raid Frames). Kingdom Hearts, Fancy Frames and Classic always show power. Left / right."] = "团队样式小队框体下显示法力、怒气及能量条；该功能依赖游戏“选项 → 界面 → 团队框体 → 显示资源条”。王国之心、华丽框体与经典风格始终显示资源条。左右方向键调整。",
