    ["Numbers, gray and glows on your buttons."] = "技能按钮的冷却数字、置灰和高亮效果。",
    ["On (to start): holding "] = "启用（默认）：按住 ",
    ["On Cooldown"] = "正在冷却",
    ["On the game's bar. A moves it, X clears it."] = "在游戏原生动作条中；按 A 移动，按 X 清除绑定。",
    ["On: Interact shoots your wand or bow at an enemy in range."] = "开启后，对有效射程内的敌人按交互键会用魔杖或弓发动攻击。",
    ["On: at a banker, X moves the item the game's cursor is on to the bank, or back to your bags, in one press."] = "与银行 NPC 对话时，对光标选中的物品按 X，可一键在银行与背包间转移。",
    ["On: the buttons below with a hold bind do it when held about half a second; a tap does their own bind,"] = "开启后，下方设置长按操作的按钮按住约半秒便执行对应操作；短按仍执行原有绑定，",
    ["On: the picker chooses a party member. Heals go to them. Harmful spells still go to your target."] = "开启后，队友选择器指定治疗对象，友方治疗施放给该队友；攻击性法术仍作用于当前敌方目标。",
    ["On: two directions move the pick, the other two are the jumps below."] = "开启后，两个方向键用于移动选中目标，另两个执行下方配置的快捷跳转。",
    ["On: when a spell waits for you to pick an item - Feed Pet, Disenchant, an enchant or scroll, a stone, a poison, Pick Lock - a small bag comes up with only the items it can go on (only food your pet eats, only what you can disenchant). D-pad picks, A puts it on (Disenchant asks first), B cancels. Out of a fight. Off: the game's own bags."] = "开启后，当喂养宠物、分解、附魔、使用卷轴、磨刀石、毒药或开锁等操作需要选择物品时，会显示仅包含有效物品的迷你背包（例如宠物能吃的食物，或当前能分解的装备）。使用十字方向键选择，按 A 应用（分解会先确认），按 B 取消。仅脱战可用。关闭则使用游戏原生背包。",
    ["On: when someone in your group or guild has a newer Controller Forever, one line in chat says it's out (once a session); they hear your version too. Off: neither."] = "开启后，当小队或公会中的其他玩家使用更新版本的 Controller Forever 时，聊天栏会提示一次；对方也会收到你的版本信息。关闭后双方都不会交换版本提示。",
    ["On: with no trigger held, every bar is lit like the one in use. Hold a trigger (or LB / RB) and the others fade as usual. Off: only the bar in use is lit."] = "开启后，未按扳机键时所有动作条均正常高亮；按住扳机键或 LB／RB 时，其他动作条会按原设置淡出。关闭后始终只高亮当前使用的动作条。",
    ["One button buffs or cleanses the next player who needs it. Their settings: the Party tab."] = "单键为下一位需要增益或驱散的队友施法。具体设置见“队伍”标签。",
    ["One button eats your best food, drinks your best water, or both."] = "一个按键使用背包中最合适的食物、饮水，或同时进行吃喝操作。",
    ["One more bar of its own buttons, binds and spot (up to 6 in all). It starts on, in a row at the top of the screen."] = "添加一条独立的额外动作条，拥有自己的按钮、绑定和位置（最多 6 条）；初始显示在屏幕顶部。",
    ["One pick for the lines below: Clean (a thin black edge), Glass (see-through, thin white edge), "] = "下方外观预设包括“简洁”（黑色细边）、“玻璃”（透明、白色细边）、 ",
    ["Only marks the button your voice chat app talks with: it does nothing in the game (a press only shows a reminder). It's also in All Keybinds."] = "仅标记语音聊天工具使用的按键，不会在游戏中执行操作（按下时只显示提示）。也可在“全部按键绑定”中设置。",
    ["Open a wheel from any button"] = "通过任意按钮打开轮盘",
