    ["Opens Edit Layout on your buttons, all together: the D-pad moves them, LT / RT size them, X then left / right"] = "打开整体按键布局编辑：方向键移动全部按钮，LT／RT 调整大小；按 X 后通过左右方向键调整两侧距离",
